-- ============================================================================
-- 0050_deskripsi_panjang_kasual.sql
--
-- Deskripsi panjang (halaman detail profesi) ditulis ulang untuk 366 profesi
-- aktif, permintaan Nico 3 November 2026: deskripsi lama hasil rakitan
-- otomatis dari data O*NET (description_source = generate_dari_dna) terlalu
-- kaku untuk siswa SMP/SMA dan mahasiswa.
--
--   * 2 paragraf, masing-masing maks 300 karakter, dipisah satu baris kosong.
--     Paragraf 1: apa pekerjaannya. Paragraf 2: suasana kerja, cocok untuk
--     siapa, dan jalur pendidikan/sertifikasinya.
--   * Nada santai menyapa "kamu", tapi isinya faktual per profesi.
--   * description_source diganti 'kurasi' untuk semua yang diisi di sini.
--
-- Deskripsi singkat untuk kartu (0049) tidak berubah.
--
-- Jalankan setelah 0049. Aman diulang.
-- ============================================================================

begin;

update public.careers c
set career_description = v.p1 || E'\n\n' || v.p2,
    description_source = 'kurasi'
from (values
  ('Frontend Developer', 'Setiap tombol, menu, dan animasi yang kamu klik di sebuah website ada yang membangunnya, dan itulah kerjaan frontend developer. Mereka mengubah desain dari tim UI/UX jadi halaman yang bisa dipakai, pakai HTML, CSS, JavaScript, dan framework seperti React.', 'Tantangannya bikin tampilan yang cepat, rapi di semua ukuran layar, dan enak dipakai siapa saja. Cocok buat kamu yang suka ngoding sekaligus peka soal visual. Banyak yang mulai dari D3 atau S1 informatika, tapi portofolio proyek sering lebih dilihat daripada ijazah.'),
  ('Backend Developer', 'Kalau frontend itu bagian yang kamu lihat, backend adalah mesin di baliknya. Backend developer menulis logika server, membangun API, dan mengatur database supaya data login, transaksi, atau pesananmu tersimpan dan diproses dengan benar.', 'Kerjanya banyak berpikir soal keamanan, kecepatan, dan bagaimana sistem tetap kuat saat dipakai ribuan orang sekaligus. Cocok buat kamu yang suka logika dan memecahkan masalah. Bahasa yang sering dipakai antara lain Python, Go, Java, dan Node.js.'),
  ('Fullstack Developer', 'Fullstack developer bisa mengerjakan dua sisi aplikasi sekaligus: tampilan yang dilihat pengguna dan server yang memproses datanya. Mereka bisa membangun satu fitur dari halaman depan sampai ke database tanpa harus menunggu orang lain.', 'Peran ini banyak dicari startup yang timnya masih kecil dan butuh orang serba bisa. Cocok buat kamu yang penasaran dengan cara kerja aplikasi secara utuh. Biasanya ditempuh lewat S1 informatika atau sistem informasi, ditambah banyak latihan bikin proyek sendiri.'),
  ('Mobile Developer (Android)', 'Aplikasi di HP Android yang kamu pakai tiap hari, dari ojek online sampai m-banking, dibuat oleh Android developer. Mereka menulis kode dengan Kotlin atau Java supaya aplikasi berjalan mulus di berbagai merek dan ukuran HP.', 'Selain bikin fitur, mereka juga memastikan aplikasi hemat baterai, tidak gampang crash, dan lolos saat diunggah ke Play Store. Pengguna Android di Indonesia sangat banyak, jadi kebutuhan developernya juga tinggi. Bisa dimulai dari D3 atau S1 informatika.'),
  ('Mobile Developer (iOS)', 'iOS developer membuat aplikasi khusus untuk iPhone dan iPad dengan bahasa Swift. Mereka mengikuti standar desain Apple yang ketat supaya aplikasinya terasa rapi, cepat, dan nyaman dipakai.', 'Pekerjaannya mencakup membangun fitur, menguji di berbagai versi iPhone, sampai merilis aplikasi ke App Store. Cocok buat kamu yang detail dan suka ekosistem Apple. Umumnya lulusan S1 informatika, dan kamu butuh Mac untuk mulai belajar.'),
  ('Mobile Developer', 'Mobile developer membuat aplikasi yang bisa jalan di Android dan iPhone sekaligus dari satu kode, biasanya pakai Flutter atau React Native. Cara ini bikin perusahaan bisa merilis aplikasi lebih cepat dan hemat biaya.', 'Kesehariannya membangun tampilan, menyambungkan aplikasi ke server, dan memperbaiki bug yang muncul di HP pengguna. Banyak startup dan perusahaan digital Indonesia memakai pendekatan ini. Cocok buat kamu yang ingin karyanya langsung dipakai banyak orang.'),
  ('Data Analyst', 'Data analyst mengubah tumpukan angka jadi cerita yang bisa dipahami. Misalnya, kenapa penjualan turun bulan ini atau produk mana yang paling disukai pelanggan. Alatnya antara lain Excel, SQL, dan tools visualisasi seperti Tableau atau Looker.', 'Hasil kerjanya dipakai atasan untuk mengambil keputusan, jadi kemampuan menjelaskan sama pentingnya dengan kemampuan menghitung. Cocok buat kamu yang teliti dan suka mencari pola. Jurusannya bisa beragam, dari statistika, matematika, sampai informatika.'),
  ('Business Intelligence Developer', 'Business intelligence developer membangun dashboard dan laporan otomatis yang dipakai perusahaan untuk memantau kinerja setiap hari. Mereka menyiapkan data dari berbagai sistem lalu menyajikannya dalam grafik yang mudah dibaca.', 'Bedanya dengan data analyst, BI developer lebih fokus membangun sistem laporannya supaya orang lain bisa melihat angka terbaru tanpa harus bertanya. Cocok buat kamu yang suka data sekaligus teknis. Biasanya lulusan S1 sistem informasi atau informatika.'),
  ('Data Engineer', 'Sebelum data bisa dianalisis, ada yang harus mengumpulkan dan merapikannya. Itulah data engineer. Mereka membangun pipeline yang mengalirkan data dari aplikasi, sensor, atau transaksi ke gudang data secara otomatis dan rapi.', 'Pekerjaannya sangat teknis: menulis kode, mengatur database besar, dan memastikan data tidak hilang atau rusak. Perannya makin penting karena perusahaan sekarang mengandalkan data untuk hampir semua keputusan. Umumnya lulusan S1 informatika.'),
  ('Data Scientist', 'Data scientist memakai statistik dan machine learning untuk menjawab pertanyaan sulit. Contohnya, memprediksi pelanggan mana yang akan berhenti berlangganan atau merekomendasikan produk yang kemungkinan besar kamu beli.', 'Kesehariannya mengolah data, membangun model, lalu menjelaskan hasilnya ke tim bisnis. Cocok buat kamu yang suka matematika, ngoding, dan rasa ingin tahunya tinggi. Biasanya lulusan S1 statistika, matematika, atau informatika, dan banyak yang lanjut S2.'),
  ('Machine Learning Engineer', 'Machine learning engineer membawa model AI dari tahap percobaan ke aplikasi nyata. Mereka melatih model, mengujinya, lalu memasangnya di sistem supaya bisa dipakai jutaan pengguna dengan cepat dan stabil.', 'Kalau data scientist banyak bereksperimen, ML engineer fokus membuat modelnya andal di dunia nyata. Pekerjaannya gabungan antara software engineering dan matematika. Cocok buat kamu yang kuat ngoding dan tertarik dengan AI. Umumnya lulusan S1 informatika.'),
  ('AI Engineer', 'AI engineer membangun fitur pintar berbasis model bahasa besar seperti chatbot, asisten virtual, atau sistem yang bisa menjawab pertanyaan dari dokumen perusahaan. Mereka merangkai model AI, data, dan aplikasi jadi satu solusi.', 'Ini salah satu bidang yang paling cepat berkembang, jadi kamu perlu senang belajar hal baru terus. Kesehariannya bereksperimen dengan prompt, menguji kualitas jawaban AI, dan menyambungkannya ke produk. Biasanya lulusan S1 informatika.'),
  ('Computer Vision Engineer', 'Computer vision engineer mengajari komputer untuk melihat. Mereka membangun sistem yang bisa mengenali wajah, membaca pelat nomor, mendeteksi cacat produk di pabrik, atau membantu mobil mengenali jalan.', 'Pekerjaannya melibatkan banyak data gambar dan video, model deep learning, dan pengujian di kondisi nyata. Cocok buat kamu yang suka AI dan tertarik pada hal visual. Umumnya lulusan S1 informatika atau teknik elektro, dan banyak yang lanjut S2.'),
  ('NLP Engineer', 'NLP engineer membangun sistem yang bisa memahami bahasa manusia. Hasil kerjanya ada di fitur terjemahan otomatis, chatbot layanan pelanggan, filter komentar kasar, sampai mesin pencari yang paham maksud ketikanmu.', 'Tantangan menariknya, bahasa Indonesia penuh singkatan, bahasa gaul, dan campuran bahasa daerah. Cocok buat kamu yang suka bahasa sekaligus ngoding. Biasanya lulusan S1 informatika, dengan bekal statistik dan machine learning.'),
  ('DevOps Engineer', 'DevOps engineer membuat proses merilis aplikasi jadi otomatis, cepat, dan aman. Begitu developer selesai menulis kode, sistem buatan DevOps langsung menguji, membangun, dan memasangnya ke server tanpa perlu dikerjakan manual.', 'Mereka juga memantau server supaya aplikasi tetap hidup dan cepat ditangani kalau ada gangguan. Cocok buat kamu yang suka otomasi dan senang mengutak-atik sistem. Alat yang sering dipakai antara lain Docker, Kubernetes, dan GitHub Actions.'),
  ('Cloud Engineer', 'Sekarang banyak perusahaan tidak lagi punya server sendiri, tapi menyewa di cloud seperti AWS, Google Cloud, atau Azure. Cloud engineer merancang, membangun, dan mengelola infrastruktur di sana supaya aplikasi bisa berjalan lancar.', 'Mereka juga harus pintar mengatur biaya, karena salah setting bisa bikin tagihan membengkak. Cocok buat kamu yang tertarik dengan jaringan, server, dan teknologi baru. Sertifikasi cloud sangat membantu karier di bidang ini.'),
  ('Site Reliability Engineer', 'Site reliability engineer (SRE) bertugas memastikan aplikasi besar tetap hidup dan cepat, bahkan saat diakses jutaan orang secara bersamaan. Mereka memantau sistem, mencari titik lemah, dan mengotomasi cara menanganinya.', 'Saat terjadi gangguan, SRE yang memimpin penanganan lalu mencari penyebabnya supaya tidak terulang. Cocok buat kamu yang tenang di bawah tekanan dan suka memecahkan masalah teknis. Biasanya diisi engineer berpengalaman lulusan S1 informatika.'),
  ('Cybersecurity Analyst', 'Cybersecurity analyst adalah penjaga keamanan dunia digital sebuah organisasi. Mereka memantau lalu lintas jaringan, mendeteksi aktivitas mencurigakan, dan bergerak cepat saat ada serangan seperti peretasan atau ransomware.', 'Kesehariannya membaca log, menganalisis ancaman, dan memberi saran supaya sistem makin aman. Kasus kebocoran data yang sering terjadi bikin profesi ini makin dicari. Cocok buat kamu yang teliti, waspada, dan suka teka-teki teknis.'),
  ('Penetration Tester', 'Penetration tester dibayar untuk membobol sistem secara legal. Mereka menyerang website, aplikasi, atau jaringan milik klien dengan izin resmi untuk menemukan celah keamanan sebelum dimanfaatkan peretas sungguhan.', 'Setelah menemukan celah, mereka menulis laporan dan cara memperbaikinya. Cocok buat kamu yang suka tantangan, kreatif, dan penasaran bagaimana sesuatu bisa dibobol. Sertifikasi seperti CEH atau OSCP sangat dihargai di bidang ini.'),
  ('UI/UX Designer', 'UI/UX designer merancang bagaimana sebuah aplikasi terlihat dan terasa saat dipakai. UX fokus pada alur yang mudah dipahami, sedangkan UI fokus pada tampilan seperti warna, tombol, dan tata letak.', 'Kesehariannya mewawancarai pengguna, membuat wireframe dan prototipe di Figma, lalu mengujinya. Cocok buat kamu yang peka visual dan peduli pada pengalaman orang lain. Jurusannya bisa desain, informatika, atau psikologi, yang penting portofolionya kuat.'),
  ('Product Manager', 'Product manager menentukan fitur apa yang dibangun, untuk siapa, dan kenapa itu penting. Mereka jadi penghubung antara pengguna, tim bisnis, desainer, dan engineer supaya semua bergerak ke arah yang sama.', 'Kesehariannya menganalisis data, berbicara dengan pengguna, menyusun prioritas, dan memimpin rapat tim. Kamu tidak harus jago ngoding, tapi perlu paham cara kerja teknologi. Cocok buat kamu yang suka memimpin dan berpikir dari sisi pengguna.'),
  ('QA Engineer', 'QA engineer adalah orang yang memastikan aplikasi tidak penuh bug sebelum sampai ke tanganmu. Mereka menguji setiap fitur, mencoba berbagai skenario, dan mencari celah yang mungkin terlewat oleh developer.', 'Pengujiannya bisa manual atau otomatis lewat skrip. Kemampuan menulis tes otomatis bikin peluang kariermu makin luas. Cocok buat kamu yang teliti, kritis, dan puas saat menemukan kesalahan. Bisa dimulai dari D3 atau S1 informatika.'),
  ('IT Project Manager', 'IT project manager memimpin proyek teknologi dari awal sampai selesai, misalnya membangun aplikasi baru atau mengganti sistem perusahaan. Mereka menyusun jadwal, membagi tugas, mengatur anggaran, dan menjaga semua tetap sesuai target.', 'Tantangannya menjaga komunikasi antara tim teknis dan klien yang sering punya bahasa berbeda. Cocok buat kamu yang terorganisir dan suka mengatur orang. Biasanya diisi orang yang sudah berpengalaman di bidang TI, ditambah sertifikasi seperti PMP.'),
  ('IT Support / Helpdesk', 'Laptop error, printer macet, atau lupa password email kantor? IT support yang turun tangan. Mereka membantu karyawan mengatasi masalah komputer, memasang software, dan menyiapkan perangkat kerja.', 'Pekerjaan ini sering jadi pintu masuk karier di dunia TI karena bisa dimulai dari lulusan SMK. Dari sini kamu bisa berkembang ke administrator sistem, jaringan, atau keamanan siber. Cocok buat kamu yang sabar dan senang membantu orang.'),
  ('System Administrator', 'System administrator mengelola server dan sistem yang dipakai seluruh kantor, seperti email, akun karyawan, penyimpanan file, dan backup data. Tugas mereka memastikan semuanya berjalan, aman, dan selalu ter-update.', 'Kalau ada server bermasalah tengah malam, sysadmin yang pertama dihubungi. Cocok buat kamu yang suka mengutak-atik sistem operasi seperti Linux dan Windows Server. Biasanya lulusan D3 atau S1 teknik komputer, ditambah sertifikasi.'),
  ('Network Engineer', 'Network engineer merancang dan mengelola jaringan yang menghubungkan komputer, server, dan internet di sebuah organisasi. Berkat mereka, kamu bisa terhubung ke Wi-Fi kantor dan semua data mengalir dengan aman.', 'Kesehariannya mengatur router dan switch, memantau kecepatan, dan memperbaiki gangguan jaringan. Sertifikasi seperti CCNA atau MTCNA sangat membantu. Cocok buat kamu yang suka utak-atik perangkat dan tertarik cara internet bekerja.'),
  ('Database Administrator', 'Database administrator (DBA) menjaga database perusahaan tetap aman, cepat, dan tidak kehilangan data. Database ini berisi informasi penting seperti data pelanggan, transaksi, dan stok barang.', 'Mereka mengatur siapa yang boleh mengakses data, membuat backup rutin, dan mempercepat query yang lambat. Satu kesalahan bisa berdampak besar, jadi ketelitian sangat penting. Cocok buat kamu yang rapi, teliti, dan suka SQL.'),
  ('Scrum Master / Agile Coach', 'Scrum master membantu tim pengembangan software bekerja lebih efektif dengan metode Agile. Mereka memfasilitasi rapat harian, perencanaan sprint, dan evaluasi supaya tim terus berkembang.', 'Mereka bukan bos tim, melainkan pelatih yang menyingkirkan hambatan dan menjaga semangat kerja. Cocok buat kamu yang komunikatif, sabar, dan peduli pada cara orang bekerja sama. Sertifikasi seperti PSM atau CSM sering jadi syarat.'),
  ('Digital Marketing Analyst', 'Digital marketing analyst membaca data dari iklan online, media sosial, dan website untuk tahu kampanye mana yang berhasil. Mereka menjawab pertanyaan seperti iklan mana yang paling banyak mendatangkan pembeli.', 'Dari hasil analisisnya, tim pemasaran bisa menghemat budget dan fokus ke strategi yang efektif. Alatnya antara lain Google Analytics, Meta Ads Manager, dan spreadsheet. Cocok buat kamu yang suka angka sekaligus paham tren digital.'),
  ('Game Developer', 'Game developer membangun game yang kamu mainkan, dari mekanik permainan, kontrol karakter, sampai efek visual. Mereka biasanya memakai engine seperti Unity atau Unreal.', 'Dalam tim, game developer bekerja bareng desainer, artist, dan sound designer. Industri game Indonesia terus tumbuh, termasuk studio lokal yang mendunia. Cocok buat kamu yang suka main game dan penasaran cara membuatnya. Portofolio game buatan sendiri sangat membantu.'),
  ('IT Business Analyst', 'IT business analyst menjembatani kebutuhan bisnis dengan tim teknologi. Mereka mewawancarai pengguna, memahami masalahnya, lalu menuliskannya jadi kebutuhan sistem yang jelas untuk dikerjakan developer.', 'Peran ini cocok untukmu yang suka menganalisis tapi tidak ingin full ngoding. Kemampuan bertanya, mendengar, dan menulis dokumen sangat penting. Biasanya lulusan S1 sistem informasi, manajemen, atau informatika.'),
  ('ERP Consultant / Developer', 'ERP consultant membantu perusahaan memasang dan menyesuaikan sistem ERP seperti SAP, Oracle, atau Odoo. Sistem ini mengatur keuangan, gudang, pembelian, dan SDM dalam satu platform.', 'Kesehariannya memahami proses bisnis klien, mengatur sistem, melatih pengguna, dan memperbaiki masalah. Konsultan ERP bersertifikat dibayar cukup tinggi. Cocok buat kamu yang paham bisnis dan teknologi sekaligus.'),
  ('Blockchain Developer', 'Blockchain developer membangun aplikasi di atas teknologi blockchain, misalnya smart contract, dompet kripto, atau sistem pencatatan yang tidak bisa diubah. Bahasa yang sering dipakai adalah Solidity.', 'Kesalahan kode di blockchain bisa berakibat hilangnya aset, jadi keamanan dan ketelitian sangat penting. Bidang ini masih baru dan terus berubah. Cocok buat kamu yang suka teknologi baru dan tidak takut belajar mandiri.'),
  ('IoT Engineer', 'IoT engineer menghubungkan benda sehari-hari ke internet, misalnya lampu pintar, sensor di kebun, atau mesin pabrik yang bisa dipantau dari HP. Mereka merancang perangkat keras, program, dan koneksinya.', 'Pekerjaannya gabungan elektronika, pemrograman, dan jaringan. Cocok buat kamu yang suka merakit, menyolder, dan ngoding sekaligus. Banyak yang mulai dari proyek Arduino atau ESP32. Biasanya lulusan D3 atau S1 teknik elektro atau komputer.'),
  ('Technical Writer', 'Technical writer menulis panduan, dokumentasi software, dan petunjuk teknis supaya hal rumit jadi mudah dipahami. Contohnya panduan pemakaian aplikasi atau dokumentasi API untuk developer.', 'Mereka bekerja dekat dengan tim engineer untuk memahami produk, lalu menuliskannya dengan bahasa yang jelas. Cocok buat kamu yang suka menulis dan tertarik dengan teknologi. Kemampuan bahasa Inggris sangat membantu di bidang ini.'),
  ('Treasurer / Finance Controller', 'Treasurer atau finance controller menjaga kesehatan keuangan perusahaan. Mereka mengatur arus kas, menyusun anggaran, memantau pengeluaran, dan memastikan laporan keuangan akurat.', 'Keputusan mereka menentukan apakah perusahaan punya cukup uang untuk gaji, investasi, atau ekspansi. Cocok buat kamu yang teliti, tegas, dan suka angka. Biasanya lulusan S1 akuntansi atau keuangan dengan pengalaman bertahun-tahun.'),
  ('Buyer Komoditas Pertanian', 'Buyer komoditas pertanian membeli hasil panen seperti kopi, kakao, sawit, atau gabah dari petani dan pengepul. Mereka harus jeli menilai mutu dan menawar harga terbaik untuk perusahaan.', 'Kesehariannya memantau harga pasar, mengunjungi pemasok, dan mengecek kualitas barang. Cocok buat kamu yang suka negosiasi dan tidak keberatan turun ke lapangan. Biasanya lulusan S1 agribisnis, pertanian, atau manajemen.'),
  ('Buyer', 'Buyer bertugas memilih dan membeli barang yang akan dijual perusahaan, misalnya produk di supermarket atau toko fashion. Mereka menentukan apa yang dibeli, berapa banyak, dan dari pemasok mana.', 'Mereka harus peka tren dan paham apa yang disukai pelanggan. Salah pilih barang bisa bikin stok menumpuk. Cocok buat kamu yang suka belanja dengan strategi dan jago menawar. Bisa dimulai dari D3 atau S1 manajemen.'),
  ('Purchasing Officer', 'Purchasing officer mengurus pembelian barang dan jasa yang dibutuhkan perusahaan, dari alat kantor sampai bahan baku produksi. Mereka mencari pemasok, membandingkan harga, dan membuat pesanan.', 'Tantangannya mendapatkan harga terbaik tanpa mengorbankan kualitas dan ketepatan waktu. Cocok buat kamu yang rapi, komunikatif, dan suka negosiasi. Biasanya lulusan S1 manajemen, teknik industri, atau bidang terkait.'),
  ('Surveyor Klaim Kendaraan (Asuransi)', 'Saat mobil mengalami kecelakaan dan pemiliknya mengajukan klaim asuransi, surveyor klaim yang datang memeriksa. Mereka menilai kerusakan, mengecek kronologi, dan memperkirakan biaya perbaikan.', 'Hasil penilaiannya menentukan berapa yang dibayar asuransi, jadi mereka harus jujur dan teliti. Pekerjaan ini banyak di lapangan dan bengkel. Cocok buat kamu yang paham otomotif dan tidak suka duduk seharian di kantor.'),
  ('Compliance Officer', 'Compliance officer memastikan perusahaan menjalankan bisnis sesuai aturan pemerintah dan regulator, misalnya OJK untuk bank. Mereka membaca regulasi baru dan memastikan semua divisi mematuhinya.', 'Kalau perusahaan melanggar aturan, denda dan reputasinya bisa jadi taruhan. Cocok buat kamu yang teliti, suka membaca aturan, dan berani mengingatkan orang. Biasanya lulusan S1 hukum, akuntansi, atau manajemen.'),
  ('Spesialis Urusan Regulasi', 'Spesialis urusan regulasi mengurus perizinan supaya produk boleh dijual secara legal, misalnya izin edar obat, kosmetik, atau makanan dari BPOM. Mereka menyiapkan dokumen dan berkomunikasi dengan regulator.', 'Tanpa izin yang lengkap, produk tidak bisa sampai ke pasaran. Cocok buat kamu yang rapi mengurus dokumen dan teliti membaca aturan. Banyak dibutuhkan di industri farmasi, makanan, dan alat kesehatan. Biasanya lulusan S1 farmasi atau teknologi pangan.'),
  ('Supply Chain Analyst', 'Pernah penasaran gimana barang pesananmu bisa sampai tepat waktu? Supply chain analyst menganalisis seluruh rantai pasok, dari pemasok, pabrik, gudang, sampai pengiriman, supaya barang tersedia saat dibutuhkan.', 'Kesehariannya mengolah data stok dan permintaan, mencari titik boros, dan memberi saran perbaikan. Cocok buat kamu yang suka angka dan berpikir sistematis. Biasanya lulusan S1 teknik industri, logistik, atau manajemen.'),
  ('Logistics Engineer', 'Logistics engineer merancang sistem pengiriman dan pergudangan yang efisien. Mereka menentukan rute terbaik, tata letak gudang, dan cara memindahkan barang supaya cepat dan hemat biaya.', 'Di era belanja online, peran ini makin penting karena pelanggan ingin barang sampai secepat mungkin. Cocok buat kamu yang suka memecahkan teka-teki dan berpikir efisien. Biasanya lulusan S1 teknik industri atau logistik.'),
  ('Logistics Analyst', 'Logistics analyst mengolah data pengiriman, stok, dan biaya untuk menemukan cara kerja logistik yang lebih baik. Misalnya, mencari tahu kenapa pengiriman sering terlambat ke kota tertentu.', 'Hasil analisisnya dipakai untuk memperbaiki rute, jadwal, atau jumlah stok di gudang. Cocok buat kamu yang suka Excel, data, dan dunia distribusi barang. Biasanya lulusan S1 teknik industri, logistik, atau manajemen.'),
  ('Marketing Specialist', 'Marketing specialist merancang dan menjalankan strategi supaya produk dikenal dan dibeli orang. Tugasnya mulai dari riset pasar, membuat kampanye, mengelola media sosial, sampai bekerja sama dengan influencer.', 'Mereka harus kreatif, tapi juga harus bisa membaca data untuk tahu strategi mana yang berhasil. Cocok buat kamu yang suka tren, komunikasi, dan ide-ide baru. Biasanya lulusan S1 manajemen pemasaran atau komunikasi.'),
  ('Akuntan / Auditor', 'Akuntan mencatat dan menyusun laporan keuangan, sedangkan auditor memeriksa apakah laporan itu benar dan sesuai standar. Keduanya memastikan angka-angka perusahaan bisa dipercaya.', 'Hasil kerja mereka dipakai investor, bank, dan pemerintah untuk menilai sebuah perusahaan. Cocok buat kamu yang teliti, jujur, dan nyaman dengan angka. Biasanya lulusan S1 akuntansi, dan sertifikasi seperti CA atau CPA bisa mendongkrak karier.'),
  ('Penilai Aset Bisnis', 'Penilai aset bisnis menghitung berapa nilai wajar sebuah aset, seperti mesin pabrik, saham perusahaan, atau merek dagang. Hasilnya dipakai saat jual beli perusahaan, pengajuan pinjaman, atau laporan keuangan.', 'Pekerjaannya gabungan analisis keuangan, survei lapangan, dan pemahaman industri. Cocok buat kamu yang analitis dan suka angka. Di Indonesia, penilai publik harus punya izin dari Kementerian Keuangan. Biasanya lulusan S1 akuntansi atau ekonomi.'),
  ('Penilai Properti', 'Penilai properti menaksir harga pasar tanah dan bangunan. Hasilnya dipakai bank saat memberi KPR, perusahaan saat jual beli aset, atau pemerintah saat pembebasan lahan.', 'Kesehariannya survei lokasi, mengukur bangunan, membandingkan harga sekitar, lalu menyusun laporan. Cocok buat kamu yang suka turun ke lapangan dan teliti dengan angka. Biasanya lulusan S1 teknik sipil, arsitektur, atau ekonomi.'),
  ('Analis Anggaran', 'Analis anggaran menyusun dan memantau rencana keuangan perusahaan atau instansi. Mereka membantu menentukan berapa dana untuk setiap divisi dan mengecek apakah pengeluaran sesuai rencana.', 'Kalau ada pengeluaran yang membengkak, merekalah yang pertama mengingatkan. Cocok buat kamu yang teliti, rapi, dan suka Excel. Banyak dibutuhkan di perusahaan swasta maupun instansi pemerintah. Biasanya lulusan S1 akuntansi atau ekonomi.'),
  ('Analis Kredit', 'Analis kredit menilai apakah seseorang atau perusahaan layak diberi pinjaman. Mereka memeriksa penghasilan, riwayat kredit, dan kemampuan bayar calon peminjam sebelum bank menyetujui kredit.', 'Keputusan mereka melindungi bank dari kredit macet sekaligus membantu orang mendapatkan modal. Cocok buat kamu yang analitis, objektif, dan tidak gampang terpengaruh. Biasanya lulusan S1 ekonomi, akuntansi, atau manajemen keuangan.'),
  ('Analis Keuangan & Investasi', 'Analis keuangan dan investasi mempelajari laporan keuangan perusahaan, kondisi pasar, dan tren ekonomi untuk menentukan investasi yang menguntungkan, misalnya saham mana yang layak dibeli.', 'Rekomendasi mereka dipakai manajer investasi, bank, atau perusahaan untuk mengambil keputusan besar. Cocok buat kamu yang suka mengikuti berita ekonomi dan nyaman dengan angka. Sertifikasi seperti CFA atau WMI sangat dihargai.'),
  ('Perencana Keuangan', 'Perencana keuangan membantu orang mengatur uangnya, mulai dari menabung, dana darurat, investasi, asuransi, sampai dana pensiun. Mereka menyusun rencana yang sesuai dengan tujuan dan kondisi tiap klien.', 'Pekerjaan ini banyak berbicara dengan orang dan butuh kepercayaan klien. Cocok buat kamu yang suka mengatur uang dan senang membantu orang mencapai mimpinya. Sertifikasi CFP sangat membantu untuk berpraktik secara profesional.'),
  ('Underwriter Asuransi', 'Underwriter asuransi menilai seberapa besar risiko calon nasabah sebelum polis diterbitkan. Misalnya, mengecek riwayat kesehatan untuk asuransi jiwa atau kondisi bangunan untuk asuransi properti.', 'Dari penilaian itu mereka menentukan apakah pengajuan diterima dan berapa preminya. Cocok buat kamu yang analitis, teliti, dan tegas mengambil keputusan. Biasanya lulusan S1 aktuaria, statistika, ekonomi, atau kesehatan.'),
  ('Analis Risiko Keuangan', 'Analis risiko keuangan mengukur dan mengendalikan potensi kerugian perusahaan, misalnya akibat kredit macet, perubahan kurs, atau gejolak pasar. Mereka membuat model dan skenario untuk memperkirakan dampaknya.', 'Hasil analisisnya membantu perusahaan bersiap sebelum masalah terjadi. Cocok buat kamu yang suka matematika, statistik, dan berpikir jauh ke depan. Biasanya lulusan S1 keuangan, statistika, atau matematika.'),
  ('Pemeriksa Lembaga Keuangan', 'Pemeriksa lembaga keuangan mengawasi bank, asuransi, dan perusahaan pembiayaan supaya tetap sehat dan patuh aturan. Mereka biasanya bekerja di lembaga pengawas seperti OJK atau Bank Indonesia.', 'Tugasnya memeriksa laporan, mewawancarai manajemen, dan menemukan potensi pelanggaran. Pekerjaan ini penting untuk melindungi uang nasabah. Cocok buat kamu yang teliti dan berintegritas tinggi. Biasanya lulusan S1 akuntansi, ekonomi, atau hukum.'),
  ('Konselor Pengelolaan Utang', 'Konselor pengelolaan utang membantu orang yang kewalahan dengan cicilan dan utang. Mereka menganalisis kondisi keuangan klien, menyusun rencana pelunasan, dan kadang membantu bernegosiasi dengan kreditur.', 'Banyak klien datang dalam keadaan stres, jadi empati sama pentingnya dengan kemampuan menghitung. Cocok buat kamu yang sabar, peduli, dan paham soal keuangan. Biasanya lulusan S1 ekonomi atau manajemen keuangan.'),
  ('Account Officer', 'Account officer di bank mencari dan membina nasabah, terutama untuk produk kredit. Mereka menawarkan pinjaman, membantu nasabah menyiapkan berkas, dan memproses pengajuan sampai disetujui.', 'Pekerjaannya banyak bertemu orang, baik pengusaha kecil maupun perusahaan besar. Biasanya ada target yang harus dicapai. Cocok buat kamu yang supel, suka jalan, dan paham dasar keuangan. Biasanya lulusan S1 ekonomi atau manajemen.'),
  ('Pemeriksa Pajak', 'Pemeriksa pajak bertugas mengecek apakah wajib pajak, baik perorangan maupun perusahaan, sudah membayar pajak dengan benar. Mereka biasanya bekerja di Direktorat Jenderal Pajak.', 'Kesehariannya meneliti laporan keuangan, meminta dokumen, dan menghitung ulang kewajiban pajak. Hasil kerjanya ikut menentukan penerimaan negara. Cocok buat kamu yang teliti dan berintegritas. Banyak yang masuk lewat PKN STAN atau jalur CPNS.'),
  ('Analis Kuantitatif Keuangan', 'Analis kuantitatif keuangan, sering disebut quant, membangun model matematika dan program komputer untuk menganalisis investasi, menghitung risiko, atau membuat strategi trading otomatis.', 'Pekerjaan ini menggabungkan matematika tingkat lanjut, statistik, dan pemrograman seperti Python. Banyak dibutuhkan di bank, manajer investasi, dan perusahaan sekuritas. Cocok buat kamu yang jago matematika dan tertarik dunia pasar modal.'),
  ('Fraud Investigator', 'Fraud investigator menyelidiki dugaan kecurangan keuangan, misalnya penggelapan dana, klaim asuransi palsu, atau penipuan transaksi online. Mereka mengumpulkan bukti dan menelusuri aliran uang.', 'Pekerjaannya seperti detektif di dunia keuangan: membaca dokumen, mewawancarai orang, dan menyusun laporan yang bisa dipakai di jalur hukum. Cocok buat kamu yang teliti, kritis, dan berani. Biasanya lulusan S1 akuntansi atau hukum.'),
  ('Health Informatics Specialist', 'Health informatics specialist mengelola sistem informasi di rumah sakit dan layanan kesehatan, seperti rekam medis elektronik dan sistem antrean pasien. Mereka memastikan data kesehatan tersimpan rapi dan aman.', 'Peran ini menjembatani dunia medis dan teknologi, jadi kamu perlu paham keduanya. Kebutuhannya terus naik seiring digitalisasi layanan kesehatan. Cocok buat kamu yang tertarik kesehatan tapi lebih suka bekerja dengan sistem dan data.'),
  ('Network Support Specialist', 'Network support specialist menangani gangguan jaringan dan perangkat komputer yang dipakai sehari-hari. Kalau internet kantor putus atau komputer tidak bisa terhubung ke server, merekalah yang mencari penyebabnya.', 'Kesehariannya memeriksa kabel, mengatur perangkat jaringan, dan membantu pengguna lewat telepon atau langsung. Cocok buat kamu yang suka utak-atik perangkat dan sabar menghadapi orang. Peran ini bisa jadi batu loncatan ke network engineer.'),
  ('Telecommunications Engineer', 'Telecommunications engineer merancang dan merawat jaringan telekomunikasi yang memungkinkan kamu menelepon, chatting, dan internetan. Mereka mengurus perangkat seperti BTS, fiber optik, dan sistem transmisi.', 'Pekerjaannya bisa di kantor untuk perencanaan maupun di lapangan untuk instalasi dan perbaikan. Cocok buat kamu yang tertarik pada sinyal, jaringan, dan teknologi seluler. Biasanya lulusan D3 atau S1 teknik telekomunikasi atau elektro.'),
  ('Database Architect', 'Database architect merancang struktur database dari awal supaya data perusahaan tersimpan rapi, aman, dan mudah diakses meski jumlahnya terus membesar. Desain mereka menentukan cepat lambatnya sebuah aplikasi.', 'Mereka memilih teknologi database yang tepat dan menetapkan standar yang diikuti tim developer. Biasanya diisi orang yang sudah berpengalaman sebagai DBA atau developer. Cocok buat kamu yang suka berpikir sistematis dan jangka panjang.'),
  ('Programmer', 'Programmer menulis, menguji, dan memperbaiki kode program sesuai kebutuhan yang sudah dirancang. Hasil kerjanya bisa berupa aplikasi kantor, sistem kasir, atau program yang berjalan di balik layar.', 'Kesehariannya banyak di depan layar, membaca kode, mencari bug, dan belajar teknologi baru. Cocok buat kamu yang sabar, logis, dan suka memecahkan masalah. Banyak programmer yang belajar otodidak, tapi lulusan informatika biasanya lebih mudah memulai.'),
  ('Web Administrator', 'Web administrator mengelola website perusahaan supaya selalu online, aman, dan isinya ter-update. Mereka mengurus hosting, domain, sertifikat keamanan, dan memperbaiki kalau website tiba-tiba error.', 'Mereka juga memantau kecepatan dan keamanan website dari serangan. Cocok buat kamu yang suka mengurus website dan teliti dengan detail teknis. Kemampuan dasar HTML, CMS seperti WordPress, dan server Linux sangat membantu.'),
  ('GIS Analyst', 'GIS analyst mengolah data peta dan lokasi menjadi informasi yang berguna. Misalnya, menentukan lokasi terbaik untuk membuka toko, memetakan daerah rawan banjir, atau merencanakan jalur distribusi.', 'Alat utamanya software pemetaan seperti ArcGIS atau QGIS, ditambah data dari satelit dan survei lapangan. Cocok buat kamu yang suka peta, geografi, dan analisis data. Biasanya lulusan D3 atau S1 geografi, geodesi, atau planologi.'),
  ('Document Controller', 'Document controller mengelola semua dokumen penting dalam proyek atau perusahaan, seperti gambar teknik, kontrak, dan laporan. Mereka memastikan setiap dokumen tercatat, versinya benar, dan mudah ditemukan.', 'Peran ini sangat dibutuhkan di proyek konstruksi, migas, dan manufaktur yang dokumennya bisa ribuan. Satu dokumen salah versi bisa bikin pekerjaan kacau. Cocok buat kamu yang rapi, teliti, dan terorganisir.'),
  ('Security Engineer', 'Security engineer membangun pertahanan sistem dari serangan siber. Mereka memasang firewall, mengatur akses, mengenkripsi data, dan menguji apakah pengamanan yang dibuat benar-benar kuat.', 'Kalau cybersecurity analyst memantau serangan, security engineer yang membangun bentengnya. Cocok buat kamu yang suka keamanan dan punya dasar jaringan serta pemrograman yang kuat. Sertifikasi keamanan seperti CompTIA Security+ sangat membantu.'),
  ('Digital Forensics Analyst', 'Digital forensics analyst menyelidiki bukti digital dari kejahatan, misalnya isi HP pelaku, jejak peretasan di server, atau file yang sengaja dihapus. Mereka memulihkan dan menganalisis data tanpa merusak keasliannya.', 'Hasil temuan mereka bisa dipakai sebagai bukti di pengadilan, jadi prosedurnya harus sangat hati-hati. Cocok buat kamu yang suka investigasi dan teknologi. Banyak bekerja di kepolisian, konsultan keamanan, atau tim keamanan perusahaan.'),
  ('Solutions Architect', 'Solutions architect merancang gambaran besar sistem teknologi untuk memecahkan masalah bisnis. Mereka menentukan teknologi apa yang dipakai, bagaimana sistem saling terhubung, dan berapa perkiraan biayanya.', 'Mereka sering bertemu klien untuk memahami kebutuhan, lalu menerjemahkannya ke tim teknis. Biasanya diisi engineer senior dengan pengalaman luas. Cocok buat kamu yang suka berpikir strategis dan bisa menjelaskan hal teknis dengan sederhana.'),
  ('Aktuaris', 'Aktuaris memakai matematika dan statistik untuk menghitung risiko di masa depan, terutama di asuransi dan dana pensiun. Misalnya, menghitung berapa premi yang adil untuk asuransi jiwa seseorang.', 'Profesi ini termasuk yang paling dicari dan bergaji tinggi di industri keuangan, karena jumlah aktuaris bersertifikat di Indonesia masih sedikit. Cocok buat kamu yang jago matematika. Kamu perlu lulus ujian sertifikasi dari Persatuan Aktuaris Indonesia.'),
  ('Operations Research Analyst', 'Operations research analyst memakai model matematika untuk mencari cara terbaik menjalankan sesuatu. Contohnya, menyusun jadwal penerbangan, mengatur rute kurir, atau menentukan jumlah kasir yang optimal.', 'Hasil kerjanya bisa menghemat biaya dan waktu dalam jumlah besar. Cocok buat kamu yang suka matematika, logika, dan teka-teki optimasi. Biasanya lulusan S1 matematika, statistika, atau teknik industri.'),
  ('Statistician', 'Statistician mengumpulkan, mengolah, dan menganalisis data dengan metode statistik untuk menjawab pertanyaan penting. Hasilnya dipakai di survei pemerintah, riset pasar, penelitian kesehatan, dan banyak bidang lain.', 'Mereka merancang survei, menentukan sampel, dan memastikan kesimpulan yang diambil benar-benar didukung data. Banyak bekerja di BPS, lembaga riset, dan perusahaan. Cocok buat kamu yang teliti dan suka angka. Biasanya lulusan S1 statistika.'),
  ('Biostatistician', 'Biostatistician menerapkan statistik di bidang kesehatan dan biologi, misalnya menganalisis hasil uji klinis obat atau vaksin. Merekalah yang membantu memastikan apakah sebuah obat benar-benar efektif.', 'Pekerjaannya banyak berkolaborasi dengan dokter dan peneliti. Cocok buat kamu yang suka statistik dan tertarik pada dunia kesehatan. Umumnya lulusan S1 statistika atau kesehatan masyarakat yang melanjutkan ke S2.'),
  ('Clinical Data Manager', 'Clinical data manager mengelola data dari uji klinis obat atau alat kesehatan. Mereka memastikan data pasien yang dikumpulkan dari berbagai rumah sakit lengkap, akurat, dan sesuai standar internasional.', 'Data yang rapi sangat penting karena dipakai untuk memutuskan apakah obat boleh beredar. Cocok buat kamu yang teliti, rapi, dan tertarik di dunia kesehatan. Biasanya lulusan S1 farmasi, kesehatan, statistika, atau sistem informasi.'),
  ('HSE Engineer', 'HSE engineer menjaga keselamatan, kesehatan kerja, dan lingkungan di tempat kerja berisiko seperti pabrik, tambang, atau proyek konstruksi. Mereka mengidentifikasi bahaya dan membuat prosedur supaya pekerja pulang dengan selamat.', 'Kesehariannya inspeksi lapangan, memberi pelatihan keselamatan, dan menyelidiki kalau terjadi kecelakaan. Cocok buat kamu yang tegas, peduli, dan tidak takut turun ke lapangan. Sertifikasi Ahli K3 sangat dibutuhkan di bidang ini.'),
  ('Fire Protection Engineer', 'Fire protection engineer merancang sistem pencegahan dan pemadaman kebakaran di gedung, pabrik, atau mal. Contohnya sprinkler, alarm kebakaran, hidran, dan jalur evakuasi.', 'Desain mereka bisa menyelamatkan banyak nyawa saat terjadi kebakaran. Pekerjaannya melibatkan perhitungan teknis, gambar desain, dan inspeksi bangunan. Cocok buat kamu yang teliti dan suka teknik. Biasanya lulusan S1 teknik mesin atau sipil.'),
  ('Industrial Engineer', 'Industrial engineer mencari cara supaya proses kerja lebih efisien. Mereka menganalisis alur produksi, menghilangkan pemborosan, dan menata ulang cara kerja supaya hasil lebih banyak dengan biaya lebih kecil.', 'Ilmunya bisa dipakai di mana saja, dari pabrik, rumah sakit, sampai perusahaan logistik dan e-commerce. Cocok buat kamu yang suka berpikir sistematis dan senang memperbaiki sesuatu. Biasanya lulusan S1 teknik industri.'),
  ('Validation Engineer', 'Validation engineer memastikan mesin, peralatan, dan proses produksi benar-benar bekerja sesuai standar. Peran ini sangat penting di industri farmasi dan alat kesehatan, di mana kesalahan kecil bisa berbahaya.', 'Kesehariannya menyusun rencana pengujian, menjalankan tes, dan mendokumentasikan hasilnya dengan sangat detail. Cocok buat kamu yang teliti dan suka bekerja dengan prosedur yang jelas. Biasanya lulusan S1 teknik, farmasi, atau kimia.'),
  ('Manufacturing Engineer', 'Manufacturing engineer merancang dan memperbaiki proses pembuatan produk di pabrik. Mereka menentukan mesin, urutan kerja, dan cara produksi supaya produk dibuat cepat, murah, dan berkualitas.', 'Kalau ada masalah di lini produksi, mereka yang mencari solusinya. Pekerjaannya banyak di lantai pabrik, bukan hanya di meja. Cocok buat kamu yang suka mesin dan senang melihat hasil kerja nyata. Biasanya lulusan S1 teknik mesin atau industri.'),
  ('Naval Architect & Marine Engineer', 'Naval architect dan marine engineer merancang kapal, dari bentuk lambung, struktur, sampai sistem mesin dan kelistrikannya. Mereka memastikan kapal stabil, kuat, dan aman berlayar.', 'Sebagai negara kepulauan, Indonesia butuh banyak kapal, dari kapal penumpang sampai kapal kargo. Pekerjaannya bisa di galangan kapal, biro desain, atau perusahaan pelayaran. Biasanya lulusan S1 teknik perkapalan atau sistem perkapalan.'),
  ('Materials Engineer', 'Materials engineer meneliti dan memilih bahan yang tepat untuk sebuah produk, misalnya logam untuk mesin, plastik untuk kemasan, atau komposit untuk pesawat. Mereka menguji kekuatan, ketahanan, dan sifat bahan.', 'Pilihan bahan yang tepat bisa bikin produk lebih ringan, kuat, dan murah. Cocok buat kamu yang suka kimia, fisika, dan bereksperimen di laboratorium. Biasanya lulusan S1 teknik material, metalurgi, atau kimia.'),
  ('Mechanical Engineer', 'Mechanical engineer merancang, menguji, dan memperbaiki mesin serta peralatan mekanis, dari mesin pabrik, AC, pompa, sampai komponen kendaraan. Mereka banyak memakai software desain seperti AutoCAD dan SolidWorks.', 'Bidang ini sangat luas, jadi lulusannya bisa bekerja di manufaktur, energi, otomotif, hingga konstruksi. Cocok buat kamu yang suka membongkar barang dan penasaran cara kerjanya. Biasanya lulusan S1 teknik mesin.'),
  ('Automotive Engineer', 'Automotive engineer merancang dan menguji kendaraan beserta komponennya, mulai dari mesin, rem, suspensi, sampai sistem kelistrikan. Sekarang bidang ini juga makin banyak menggarap kendaraan listrik.', 'Pekerjaannya bisa di pabrik otomotif, pusat riset, atau pemasok komponen. Cocok buat kamu yang suka mobil dan motor serta penasaran bagaimana kendaraan dibuat. Biasanya lulusan S1 teknik mesin atau teknik otomotif.'),
  ('Mining & Geological Engineer', 'Mining dan geological engineer merencanakan kegiatan tambang, dari mencari lokasi cadangan mineral sampai menentukan cara menambang yang aman dan efisien. Mereka juga menilai kondisi batuan dan tanah.', 'Pekerjaannya sering di lokasi terpencil dengan sistem kerja rotasi, tapi gajinya umumnya tinggi. Cocok buat kamu yang suka alam, tidak takut kerja lapangan, dan kuat secara fisik. Biasanya lulusan S1 teknik pertambangan atau geologi.'),
  ('Nuclear Engineer', 'Nuclear engineer merancang dan mengawasi sistem yang memakai energi nuklir, seperti reaktor riset, peralatan medis radiasi, atau pembangkit listrik. Keselamatan adalah prioritas nomor satu di bidang ini.', 'Di Indonesia, peran ini banyak ada di BRIN dan BAPETEN, serta terus dibahas seiring rencana pembangkit nuklir. Cocok buat kamu yang kuat di fisika dan matematika. Biasanya lulusan S1 teknik nuklir atau fisika.'),
  ('Petroleum Engineer', 'Petroleum engineer merancang cara mengebor dan mengangkat minyak serta gas dari dalam bumi seefisien mungkin. Mereka menghitung kondisi reservoir, merancang sumur, dan mengawasi proses produksi.', 'Pekerjaannya bisa di kantor maupun di anjungan lepas pantai dengan sistem rotasi. Gajinya termasuk tinggi di dunia teknik. Cocok buat kamu yang suka fisika, kimia, dan tantangan lapangan. Biasanya lulusan S1 teknik perminyakan.'),
  ('Energy Engineer', 'Energy engineer merancang cara memakai energi secara efisien dan ramah lingkungan. Mereka mengaudit pemakaian listrik gedung atau pabrik, lalu merancang solusi seperti panel surya atau sistem hemat energi.', 'Bidang ini makin penting karena dunia sedang beralih ke energi bersih. Cocok buat kamu yang peduli lingkungan sekaligus suka hitung-hitungan teknik. Biasanya lulusan S1 teknik mesin, elektro, atau teknik energi.'),
  ('Mechatronics Engineer', 'Mechatronics engineer merancang sistem yang memadukan mesin, elektronika, dan program komputer. Contohnya mesin otomatis di pabrik, lengan robot, atau perangkat pintar di rumah.', 'Karena menggabungkan banyak ilmu, mereka sering jadi penghubung antara tim mekanik, elektro, dan software. Cocok buat kamu yang suka merakit dan ngoding sekaligus. Biasanya lulusan S1 teknik mekatronika, mesin, atau elektro.'),
  ('Robotics Engineer', 'Robotics engineer merancang, membangun, dan memprogram robot, dari lengan robot di pabrik mobil sampai robot pengantar barang di gudang. Mereka membuat robot bisa bergerak, merasakan, dan mengambil keputusan.', 'Pekerjaannya menggabungkan mekanik, elektronika, dan pemrograman. Banyak yang mulai tertarik dari lomba robotik di sekolah. Cocok buat kamu yang suka menciptakan sesuatu yang bisa bergerak. Biasanya lulusan S1 teknik elektro, mesin, atau mekatronika.'),
  ('Wind Energy Engineer', 'Wind energy engineer merancang dan mengembangkan pembangkit listrik tenaga angin. Mereka memilih lokasi dengan angin yang cukup, merancang turbin, dan menghitung berapa listrik yang bisa dihasilkan.', 'Indonesia sudah punya PLTB seperti di Sidrap dan Jeneponto, dan proyek energi terbarukan terus bertambah. Cocok buat kamu yang peduli lingkungan dan suka teknik. Biasanya lulusan S1 teknik mesin, elektro, atau fisika.'),
  ('Solar Energy Engineer', 'Solar energy engineer merancang sistem pembangkit listrik tenaga surya, dari panel di atap rumah sampai PLTS skala besar. Mereka menghitung kebutuhan listrik, memilih komponen, dan merancang pemasangannya.', 'Dengan sinar matahari melimpah sepanjang tahun, potensi energi surya di Indonesia sangat besar. Cocok buat kamu yang peduli lingkungan dan suka hitung-hitungan teknik. Biasanya lulusan S1 teknik elektro atau teknik energi.'),
  ('Teknisi Robotika', 'Teknisi robotika merakit, memprogram, dan merawat robot yang dipakai di pabrik, misalnya robot las atau robot pengangkat barang. Kalau robot berhenti bekerja, mereka yang memperbaikinya.', 'Pekerjaannya banyak di lantai pabrik dengan tangan langsung menyentuh mesin. Cocok buat kamu yang suka praktik dan teknologi. Seiring makin banyak pabrik memakai otomasi, kebutuhannya terus naik. Biasanya lulusan D3 mekatronika atau elektro.'),
  ('Staff Industrial Engineering', 'Staff industrial engineering menyusun standar kerja dan mengukur efisiensi di lini produksi. Mereka menghitung berapa lama setiap pekerjaan seharusnya selesai dan mencari cara mengurangi waktu terbuang.', 'Hasil kerjanya membantu pabrik menentukan target produksi yang realistis dan mengatur jumlah pekerja. Cocok buat kamu yang teliti, suka angka, dan senang mengamati proses. Biasanya lulusan D3 atau S1 teknik industri.'),
  ('Teknisi Mesin', 'Teknisi mesin membantu insinyur merancang, menguji, dan merawat mesin. Mereka merakit prototipe, menjalankan pengujian, mencatat hasilnya, dan memperbaiki mesin yang rusak.', 'Pekerjaannya sangat praktis dan banyak di bengkel atau pabrik. Cocok buat kamu yang suka bekerja dengan tangan dan memahami cara kerja mesin. Biasanya lulusan SMK atau D3 teknik mesin, dan bisa berkembang ke posisi supervisor.'),
  ('Teknisi Automotive Engineering', 'Teknisi automotive engineering menguji dan merawat komponen kendaraan di pabrik atau pusat riset. Mereka membantu insinyur menguji performa mesin, rem, atau sistem kelistrikan sebelum diproduksi massal.', 'Pekerjaannya banyak memakai alat ukur dan peralatan uji khusus. Cocok buat kamu yang suka otomotif dan teliti dalam mencatat data. Biasanya lulusan D3 teknik otomotif atau mesin, dan bisa lanjut ke jenjang insinyur.'),
  ('Food Scientist', 'Food scientist meneliti dan mengembangkan produk makanan dan minuman yang aman, bergizi, dan enak. Mereka bisa menciptakan rasa baru, memperpanjang daya simpan, atau mencari bahan pengganti yang lebih sehat.', 'Snack, minuman kemasan, sampai mi instan yang kamu makan melewati tangan mereka. Pekerjaannya banyak di laboratorium dan dapur riset. Cocok buat kamu yang suka kimia dan makanan. Biasanya lulusan S1 teknologi pangan atau ilmu gizi.'),
  ('Geosaintis', 'Geosaintis meneliti struktur dan proses di dalam bumi, seperti batuan, gempa, gunung api, dan air tanah. Hasil penelitiannya dipakai untuk mencari tambang dan energi, sampai memitigasi bencana.', 'Pekerjaannya gabungan kerja lapangan, laboratorium, dan analisis data. Indonesia yang rawan bencana dan kaya sumber daya alam sangat butuh geosaintis. Cocok buat kamu yang suka alam dan sains. Biasanya lulusan S1 geologi atau geofisika.'),
  ('Teknisi R&D Pangan', 'Teknisi R&D pangan membantu mengembangkan produk makanan baru di laboratorium. Mereka menguji bahan, membuat sampel resep, mengukur rasa dan tekstur, lalu mencatat hasilnya dengan rapi.', 'Mereka bekerja dekat dengan food scientist untuk menyempurnakan produk sebelum diproduksi massal. Cocok buat kamu yang suka eksperimen dapur dengan cara yang ilmiah. Biasanya lulusan D3 teknologi pangan atau analis kimia.'),
  ('Teknisi Geologi', 'Teknisi geologi membantu ahli geologi di lapangan dan laboratorium. Mereka mengambil sampel batuan dan tanah, mengoperasikan alat survei, dan menyiapkan sampel untuk dianalisis.', 'Pekerjaannya sering di lokasi tambang, eksplorasi migas, atau proyek konstruksi. Cocok buat kamu yang suka alam terbuka, kuat secara fisik, dan teliti. Biasanya lulusan D3 atau S1 geologi atau teknik pertambangan.'),
  ('QC Analyst', 'QC analyst menguji mutu bahan baku dan produk di laboratorium sebelum dikirim ke konsumen. Mereka memastikan produk seperti obat, makanan, atau kosmetik aman dan sesuai standar.', 'Kesehariannya menjalankan pengujian kimia atau mikrobiologi, mencatat hasil, dan menolak produk yang tidak lolos. Cocok buat kamu yang teliti dan suka kerja laboratorium. Biasanya lulusan D3 analis kimia, farmasi, atau teknologi pangan.'),
  ('Dosen Bisnis dan Manajemen', 'Dosen bisnis dan manajemen mengajar mahasiswa tentang cara mengelola perusahaan, pemasaran, keuangan, dan kewirausahaan. Selain mengajar, mereka juga meneliti dan membimbing skripsi.', 'Banyak dosen di bidang ini juga menjadi konsultan atau punya usaha sendiri. Cocok buat kamu yang suka berbagi ilmu dan tertarik pada dunia bisnis. Syarat minimalnya lulusan S2, dan banyak yang melanjutkan sampai S3.'),
  ('Dosen Ilmu Komputer', 'Dosen ilmu komputer mengajar pemrograman, algoritma, kecerdasan buatan, dan topik teknologi lainnya di perguruan tinggi. Mereka juga meneliti dan membimbing mahasiswa membuat proyek dan skripsi.', 'Karena teknologi berubah sangat cepat, dosen di bidang ini harus terus belajar hal baru. Cocok buat kamu yang suka teknologi dan senang mengajar. Syarat minimalnya lulusan S2 informatika atau ilmu komputer.'),
  ('Dosen Arsitektur', 'Dosen arsitektur mengajar mahasiswa merancang bangunan, dari konsep, gambar teknik, sampai maket. Mereka juga membimbing studio desain, tempat mahasiswa belajar lewat proyek nyata.', 'Banyak dosen arsitektur juga aktif sebagai arsitek praktisi. Cocok buat kamu yang suka desain, seni, dan ingin berbagi ilmu. Syarat minimalnya lulusan S2 arsitektur, dan sertifikasi arsitek jadi nilai tambah.'),
  ('Dosen Teknik', 'Dosen teknik mengajar ilmu keteknikan seperti teknik sipil, mesin, elektro, atau kimia di perguruan tinggi. Mereka mengajar di kelas, membimbing praktikum di laboratorium, dan meneliti.', 'Hasil penelitian mereka bisa berdampak langsung ke industri dan masyarakat. Cocok buat kamu yang kuat di bidang teknik dan senang membimbing orang. Syarat minimalnya lulusan S2 teknik sesuai bidangnya.'),
  ('Dosen Ilmu Pertanian', 'Dosen ilmu pertanian mengajar dan meneliti tentang tanaman, tanah, peternakan, dan teknologi pertanian. Penelitian mereka bisa membantu petani meningkatkan hasil panen.', 'Pekerjaannya gabungan mengajar di kelas, penelitian di laboratorium, dan turun ke lahan pertanian. Cocok buat kamu yang peduli pada ketahanan pangan dan suka sains. Syarat minimalnya lulusan S2 pertanian atau bidang terkait.'),
  ('Dosen Ilmu Kebumian dan Kelautan', 'Dosen ilmu kebumian dan kelautan mengajar dan meneliti tentang bumi, laut, iklim, dan bencana alam. Topiknya bisa dari gempa bumi, arus laut, sampai perubahan iklim.', 'Sebagai negara maritim yang rawan bencana, Indonesia sangat membutuhkan ahli di bidang ini. Cocok buat kamu yang suka alam dan sains. Syarat minimalnya lulusan S2 geologi, oseanografi, meteorologi, atau bidang terkait.'),
  ('Dosen Ilmu Ekonomi', 'Dosen ilmu ekonomi mengajar mahasiswa tentang cara kerja ekonomi, dari perilaku konsumen sampai kebijakan negara. Mereka juga meneliti isu seperti inflasi, kemiskinan, dan pertumbuhan ekonomi.', 'Hasil penelitiannya sering dipakai pemerintah dalam membuat kebijakan. Cocok buat kamu yang suka menganalisis isu sosial dengan data. Syarat minimalnya lulusan S2 ekonomi, dan banyak yang melanjutkan sampai S3.'),
  ('Dosen Ilmu Politik', 'Dosen ilmu politik mengajar dan meneliti tentang pemerintahan, pemilu, kebijakan publik, dan hubungan internasional. Mereka sering diminta jadi narasumber di media saat ada isu politik hangat.', 'Pekerjaannya banyak membaca, menulis, berdiskusi, dan meneliti. Cocok buat kamu yang kritis, suka berdebat, dan peduli pada isu publik. Syarat minimalnya lulusan S2 ilmu politik atau hubungan internasional.'),
  ('Dosen Psikologi', 'Dosen psikologi mengajar mahasiswa tentang perilaku dan pikiran manusia, dari perkembangan anak sampai psikologi kerja. Mereka juga meneliti dan membimbing mahasiswa melakukan penelitian.', 'Banyak dosen psikologi juga berpraktik sebagai psikolog. Cocok buat kamu yang penasaran dengan cara manusia berpikir dan suka berbagi ilmu. Syarat minimalnya lulusan S2 psikologi.'),
  ('Dosen Ilmu Kesehatan', 'Dosen ilmu kesehatan mengajar calon tenaga kesehatan, seperti calon ahli gizi, bidan, atau tenaga kesehatan masyarakat. Mereka mengajar teori, membimbing praktik, dan meneliti masalah kesehatan.', 'Hasil penelitian mereka bisa membantu memperbaiki layanan kesehatan di masyarakat. Cocok buat kamu yang punya latar kesehatan dan senang mengajar. Syarat minimalnya lulusan S2 di bidang kesehatan.'),
  ('Dosen Keperawatan', 'Dosen keperawatan mengajar dan membimbing calon perawat, baik teori di kelas maupun praktik di laboratorium dan rumah sakit. Mereka memastikan mahasiswa siap merawat pasien dengan aman.', 'Banyak dosen keperawatan punya pengalaman sebagai perawat di rumah sakit sebelumnya. Cocok buat kamu yang mencintai dunia keperawatan dan ingin mencetak perawat berkualitas. Syarat minimalnya lulusan S2 keperawatan.'),
  ('Dosen Hukum', 'Dosen hukum mengajar mahasiswa tentang hukum pidana, perdata, tata negara, dan bidang hukum lainnya. Mereka juga meneliti dan sering dimintai pendapat ahli dalam kasus hukum.', 'Banyak dosen hukum juga aktif sebagai advokat, konsultan, atau penasihat lembaga. Cocok buat kamu yang suka membaca, berdebat, dan menganalisis aturan. Syarat minimalnya lulusan S2 ilmu hukum.'),
  ('Dosen Ilmu Komunikasi', 'Dosen ilmu komunikasi mengajar tentang jurnalistik, public relations, periklanan, media digital, dan komunikasi antarmanusia. Mereka juga meneliti perkembangan media dan perilaku audiens.', 'Topiknya terus berkembang seiring munculnya media sosial dan platform baru. Cocok buat kamu yang suka media, komunikasi, dan senang berbagi ilmu. Syarat minimalnya lulusan S2 ilmu komunikasi.'),
  ('Instruktur Pendidikan Vokasi', 'Instruktur pendidikan vokasi melatih keterampilan kerja praktis seperti otomotif, las, tata boga, atau komputer di BLK, politeknik, atau lembaga pelatihan. Fokusnya membuat peserta siap kerja.', 'Pekerjaannya lebih banyak praktik daripada teori, jadi pengalaman industri sangat dihargai. Cocok buat kamu yang ahli di satu keterampilan dan senang mengajarkannya. Sertifikasi instruktur dan kompetensi dari BNSP sangat membantu.'),
  ('Guru PAUD', 'Guru PAUD mendampingi anak usia dini belajar sambil bermain. Lewat lagu, permainan, dan cerita, mereka melatih kemampuan dasar anak seperti bicara, bergerak, bersosialisasi, dan mengenal huruf.', 'Masa ini sangat penting untuk tumbuh kembang anak, jadi peran guru PAUD besar sekali. Cocok buat kamu yang sabar, ceria, dan sayang anak-anak. Biasanya lulusan D3 atau S1 Pendidikan Guru PAUD.'),
  ('Guru TK', 'Guru TK mengajar dan membimbing anak usia 4–6 tahun sebelum masuk SD. Mereka mengenalkan huruf, angka, warna, dan kebiasaan baik lewat kegiatan yang menyenangkan.', 'Selain mengajar, guru TK juga sering berkomunikasi dengan orang tua soal perkembangan anak. Cocok buat kamu yang kreatif, sabar, dan suka dunia anak. Biasanya lulusan S1 Pendidikan Guru PAUD.'),
  ('Guru SD', 'Guru SD mengajar dan membimbing siswa di tahun-tahun awal sekolah. Mereka mengajar banyak mata pelajaran sekaligus, dari membaca, berhitung, sampai pendidikan karakter.', 'Guru SD sering menjadi sosok yang paling diingat murid seumur hidup. Cocok buat kamu yang sabar, kreatif, dan senang melihat anak berkembang. Biasanya lulusan S1 PGSD, dan untuk jadi guru tetap perlu sertifikasi PPG.'),
  ('Guru SMP', 'Guru SMP mengajar satu mata pelajaran, seperti matematika, IPA, atau bahasa Inggris, kepada siswa remaja. Selain mengajar, mereka juga membimbing siswa di masa peralihan yang penuh tantangan.', 'Mereka menyusun materi, menilai tugas, dan sering juga jadi wali kelas atau pembina ekstrakurikuler. Cocok buat kamu yang menguasai satu bidang dan suka berinteraksi dengan remaja. Biasanya lulusan S1 pendidikan sesuai mata pelajaran.'),
  ('Guru Prakarya', 'Guru prakarya mengajar siswa membuat karya dan produk, seperti kerajinan, olahan makanan, atau budidaya tanaman. Lewat pelajaran ini, siswa belajar kreatif sekaligus berwirausaha.', 'Kelasnya lebih banyak praktik, jadi suasana belajar biasanya seru dan penuh karya. Cocok buat kamu yang kreatif, terampil, dan suka mengajar. Biasanya lulusan S1 pendidikan seni, tata boga, atau bidang terkait.'),
  ('Guru SMA', 'Guru SMA mengajar satu mata pelajaran secara lebih mendalam dan membantu siswa bersiap ke perguruan tinggi atau dunia kerja. Mereka sering juga menjadi tempat siswa bertanya soal masa depan.', 'Selain mengajar, guru SMA bisa membina olimpiade, organisasi siswa, atau ekstrakurikuler. Cocok buat kamu yang menguasai satu bidang dan senang membimbing anak muda. Biasanya lulusan S1 pendidikan sesuai mata pelajaran.'),
  ('Guru SMK', 'Guru SMK mengajar keterampilan kejuruan seperti otomotif, akuntansi, multimedia, atau perhotelan. Tujuannya membuat siswa siap bekerja begitu lulus sekolah.', 'Pengajarannya banyak praktik di bengkel atau laboratorium, dan sering bekerja sama dengan industri untuk program magang. Cocok buat kamu yang ahli di satu keterampilan dan suka mengajar. Biasanya lulusan S1 pendidikan teknik atau kejuruan.'),
  ('Guru Pendidikan Kesetaraan', 'Guru pendidikan kesetaraan mengajar peserta program Paket A, B, dan C, yang setara dengan SD, SMP, dan SMA. Muridnya bisa remaja putus sekolah sampai orang dewasa yang ingin melanjutkan pendidikan.', 'Karena latar belakang muridnya beragam, guru harus fleksibel dan penuh pengertian. Pekerjaan ini memberi kesempatan kedua bagi banyak orang. Cocok buat kamu yang sabar dan peduli pada pendidikan untuk semua. Biasanya lulusan S1 pendidikan.'),
  ('Guru Kursus', 'Guru kursus mengajar keterampilan atau mata pelajaran tertentu di lembaga kursus, misalnya bahasa Inggris, musik, komputer, atau bimbingan belajar. Kelasnya biasanya kecil dan fokus pada satu tujuan.', 'Jam kerjanya sering sore atau akhir pekan, jadi bisa dijalankan sambil kuliah atau bekerja. Cocok buat kamu yang menguasai satu bidang dan senang menjelaskan. Sertifikat keahlian sering lebih dilihat daripada gelar.'),
  ('Guru Pengganti', 'Guru pengganti mengajar saat guru tetap berhalangan, misalnya karena sakit, cuti melahirkan, atau tugas luar. Mereka memastikan pelajaran tetap berjalan dan siswa tidak ketinggalan materi.', 'Tantangannya harus cepat beradaptasi dengan kelas dan materi yang berbeda-beda. Pengalaman ini sering jadi jalan masuk untuk menjadi guru tetap. Cocok buat kamu yang fleksibel dan percaya diri di depan kelas. Biasanya lulusan S1 pendidikan.'),
  ('Guru Les Privat', 'Guru les privat mengajar satu atau beberapa siswa secara langsung, di rumah siswa atau secara online. Materinya disesuaikan dengan kebutuhan, misalnya persiapan ujian atau mengejar pelajaran yang tertinggal.', 'Jadwalnya fleksibel, jadi banyak mahasiswa yang menjalaninya sambil kuliah. Pendapatannya tergantung jumlah murid dan keahlianmu. Cocok buat kamu yang menguasai satu pelajaran dan sabar menjelaskan berulang kali.'),
  ('Arsiparis', 'Arsiparis mengelola arsip penting milik instansi atau perusahaan, seperti surat resmi, dokumen hukum, dan catatan sejarah. Mereka menata, merawat, dan memastikan arsip mudah ditemukan saat dibutuhkan.', 'Sekarang pekerjaannya juga mencakup arsip digital. Banyak dibutuhkan di instansi pemerintah, ANRI, dan perusahaan besar. Cocok buat kamu yang rapi, teliti, dan menghargai sejarah. Biasanya lulusan D3 atau S1 kearsipan.'),
  ('Kurator', 'Kurator memilih, meneliti, dan menata koleksi untuk dipamerkan di museum atau galeri seni. Mereka menentukan cerita apa yang ingin disampaikan pameran dan bagaimana karya disusun supaya pengunjung paham.', 'Pekerjaannya banyak meneliti, menulis, dan bekerja sama dengan seniman atau peneliti. Cocok buat kamu yang suka seni, sejarah, dan bercerita. Biasanya lulusan S1 sejarah, arkeologi, seni rupa, atau museologi.'),
  ('Konservator Museum', 'Konservator museum merawat dan memulihkan benda koleksi museum supaya tetap awet, seperti naskah kuno, lukisan, kain, atau artefak. Mereka memakai teknik dan bahan khusus agar tidak merusak benda aslinya.', 'Pekerjaannya butuh kesabaran tinggi dan tangan yang sangat hati-hati. Cocok buat kamu yang suka sejarah, seni, dan sains sekaligus. Biasanya lulusan S1 arkeologi, kimia, atau seni rupa dengan pelatihan konservasi.'),
  ('Pustakawan', 'Pustakawan mengelola koleksi perpustakaan dan membantu pengunjung menemukan informasi yang mereka butuhkan. Selain buku fisik, sekarang mereka juga mengelola e-book, jurnal online, dan database digital.', 'Mereka bisa bekerja di perpustakaan sekolah, kampus, instansi, atau perusahaan. Cocok buat kamu yang suka membaca, rapi, dan senang membantu orang mencari jawaban. Biasanya lulusan S1 ilmu perpustakaan.'),
  ('Pustakawan Tingkat Terampil', 'Pustakawan tingkat terampil melayani peminjaman dan pengembalian buku, menata koleksi di rak, dan membantu pengunjung sehari-hari di perpustakaan. Mereka menjaga perpustakaan tetap rapi dan nyaman.', 'Pekerjaannya cocok untukmu yang suka suasana tenang dan senang dikelilingi buku. Banyak tersedia di sekolah, kampus, dan perpustakaan daerah. Biasanya lulusan D3 perpustakaan, dan bisa naik jenjang dengan melanjutkan ke S1.'),
  ('Penyuluh Pertanian', 'Penyuluh pertanian membimbing petani supaya bisa bertani dengan cara yang lebih baik, misalnya memilih bibit unggul, memupuk dengan tepat, atau mengatasi hama. Mereka sering turun langsung ke sawah dan kebun.', 'Peran mereka penting untuk meningkatkan hasil panen dan kesejahteraan petani. Banyak yang bekerja sebagai ASN di dinas pertanian. Cocok buat kamu yang suka pertanian dan senang berbagi ilmu ke masyarakat. Biasanya lulusan S1 pertanian.'),
  ('Pengembang Kurikulum', 'Pengembang kurikulum merancang apa yang dipelajari siswa dan bagaimana cara mengajarkannya. Mereka menyusun materi, modul, dan cara penilaian untuk sekolah, kampus, atau lembaga pelatihan.', 'Hasil kerjanya berpengaruh ke ribuan siswa sekaligus. Banyak juga yang bekerja di perusahaan edutech untuk merancang kursus online. Cocok buat kamu yang suka pendidikan dan berpikir sistematis. Biasanya lulusan S1 pendidikan atau teknologi pendidikan.'),
  ('Asisten Guru', 'Asisten guru membantu guru mengelola kelas, menyiapkan bahan ajar, dan mendampingi siswa yang butuh perhatian lebih. Mereka membuat suasana belajar lebih teratur dan efektif.', 'Banyak dibutuhkan di sekolah internasional, sekolah swasta, dan PAUD. Pekerjaan ini bagus sebagai pengalaman awal sebelum menjadi guru. Cocok buat kamu yang sabar, suka anak-anak, dan senang membantu.'),
  ('Guru Pendamping Khusus (GPK)', 'Guru pendamping khusus (GPK) mendampingi siswa berkebutuhan khusus belajar di sekolah inklusi, misalnya anak dengan autisme, ADHD, atau disleksia. Mereka menyesuaikan cara belajar supaya anak bisa berkembang.', 'Pekerjaannya penuh tantangan, tapi juga sangat bermakna karena kamu ikut membantu anak menemukan potensinya. Cocok buat kamu yang sangat sabar dan empatik. Biasanya lulusan D3 atau S1 pendidikan luar biasa atau psikologi.'),
  ('Asisten Dosen', 'Asisten dosen membantu dosen dalam kegiatan perkuliahan, seperti memandu praktikum, menilai tugas, menyiapkan materi, dan menjawab pertanyaan mahasiswa.', 'Banyak asisten dosen adalah mahasiswa berprestasi atau lulusan baru yang ingin berkarier di dunia akademik. Pengalaman ini jadi langkah awal untuk menjadi dosen. Cocok buat kamu yang menguasai mata kuliah tertentu dan suka mengajar.'),
  ('Art Director', 'Art director memimpin arah visual sebuah kampanye, majalah, film, atau produk. Mereka menentukan gaya, warna, dan suasana yang ingin ditampilkan, lalu membimbing tim desainer dan fotografer untuk mewujudkannya.', 'Mereka harus kreatif sekaligus bisa memimpin tim dan meyakinkan klien. Biasanya posisi ini diraih setelah bertahun-tahun menjadi desainer. Cocok buat kamu yang punya selera visual kuat dan suka memimpin proyek kreatif.'),
  ('Perajin Kriya', 'Perajin kriya membuat kerajinan tangan bernilai seni, seperti batik, anyaman, keramik, ukiran kayu, atau perhiasan. Banyak produk kriya Indonesia yang dijual sampai ke luar negeri.', 'Selain keterampilan tangan, perajin sekarang juga perlu paham pemasaran online untuk menjual karyanya. Cocok buat kamu yang kreatif, sabar, dan suka membuat sesuatu dengan tangan. Bisa dipelajari lewat sekolah seni atau belajar langsung dari perajin.'),
  ('Seniman Rupa / Ilustrator', 'Seniman rupa dan ilustrator menciptakan lukisan, gambar, atau ilustrasi digital. Karyanya bisa dipakai untuk buku, kemasan produk, game, poster, atau dipamerkan di galeri.', 'Banyak ilustrator bekerja secara freelance dengan klien dari dalam maupun luar negeri. Portofolio adalah senjata utamamu di bidang ini. Cocok buat kamu yang suka menggambar dan punya gaya visual sendiri.'),
  ('Animator / VFX Artist', 'Animator dan VFX artist menghidupkan gambar jadi bergerak. Mereka membuat animasi karakter, efek ledakan, atau dunia fantasi untuk film, iklan, serial, dan game.', 'Studio animasi Indonesia makin banyak menggarap proyek lokal dan internasional. Software yang sering dipakai antara lain Blender, Maya, dan After Effects. Cocok buat kamu yang sabar, detail, dan suka film atau kartun.'),
  ('Desainer Produk (Industrial Designer)', 'Desainer produk merancang bentuk dan fungsi barang sehari-hari, seperti kursi, botol minum, alat elektronik, atau perabot. Mereka memastikan produk enak dilihat, nyaman dipakai, dan bisa diproduksi.', 'Prosesnya dari sketsa, model 3D, prototipe, sampai siap produksi. Cocok buat kamu yang kreatif dan penasaran kenapa sebuah barang dibuat seperti itu. Biasanya lulusan S1 desain produk.'),
  ('Desainer Fashion', 'Desainer fashion merancang pakaian dan koleksi mode, mulai dari ide, sketsa, memilih bahan, sampai mengawasi pembuatan contoh baju. Mereka harus peka tren sekaligus punya ciri khas sendiri.', 'Banyak desainer fashion Indonesia yang membangun brand lokal sendiri. Cocok buat kamu yang suka mode, kreatif, dan berani tampil beda. Biasanya lulusan D3 atau S1 desain mode, dan portofolio karya sangat penting.'),
  ('Perangkai Bunga (Florist)', 'Florist merangkai bunga untuk berbagai keperluan, seperti buket hadiah, dekorasi pernikahan, papan ucapan, atau hiasan acara. Mereka memilih bunga, warna, dan bentuk rangkaian yang sesuai suasana.', 'Banyak florist membuka toko sendiri dan menjual lewat media sosial. Cocok buat kamu yang kreatif, punya selera estetika, dan suka bunga. Keterampilannya bisa dipelajari lewat kursus atau belajar langsung di toko bunga.'),
  ('Graphic Designer', 'Graphic designer membuat desain visual untuk promosi, merek, dan media digital, seperti logo, poster, konten Instagram, kemasan, dan banner. Mereka menyampaikan pesan lewat gambar, warna, dan huruf.', 'Hampir semua perusahaan butuh desainer grafis, dan banyak juga yang bekerja freelance. Software yang biasa dipakai antara lain Adobe Illustrator, Photoshop, dan Figma. Cocok buat kamu yang kreatif dan peka visual.'),
  ('Interior Designer', 'Interior designer merancang ruangan supaya nyaman, fungsional, dan enak dilihat, dari rumah, kafe, kantor, sampai hotel. Mereka memilih tata letak, furnitur, warna, dan pencahayaan.', 'Prosesnya mulai dari diskusi dengan klien, membuat desain 3D, sampai mengawasi pengerjaan di lokasi. Cocok buat kamu yang suka menata ruang dan punya selera estetika. Biasanya lulusan S1 desain interior.'),
  ('Visual Merchandiser', 'Visual merchandiser menata tampilan toko supaya menarik perhatian dan mendorong orang membeli. Mereka mengatur display etalase, susunan produk, dan dekorasi sesuai musim atau promo.', 'Banyak bekerja di brand fashion, department store, dan ritel. Cocok buat kamu yang kreatif, suka fashion atau desain, dan paham perilaku belanja orang. Biasanya lulusan D3 atau S1 desain atau pemasaran.'),
  ('Desainer Set dan Panggung', 'Desainer set dan panggung merancang latar tempat cerita terjadi, untuk film, teater, konser, atau acara televisi. Mereka membuat gambar desain, memilih properti, dan mengawasi pembangunan set.', 'Desain mereka membantu penonton merasakan suasana cerita. Cocok buat kamu yang kreatif, suka seni pertunjukan, dan bisa berpikir dalam tiga dimensi. Biasanya lulusan S1 desain interior, arsitektur, atau seni rupa.'),
  ('Produser dan Sutradara', 'Produser dan sutradara memimpin pembuatan film, video, atau program dari ide sampai selesai. Produser mengurus dana, jadwal, dan tim, sedangkan sutradara mengarahkan cerita dan para pemain.', 'Pekerjaannya penuh tekanan dan jam kerja panjang, tapi hasilnya bisa ditonton jutaan orang. Banyak yang memulai dari film pendek atau konten YouTube. Cocok buat kamu yang suka bercerita dan memimpin tim kreatif.'),
  ('Direktur Program Media', 'Direktur program media merencanakan dan mengatur acara yang tayang di radio atau televisi. Mereka menentukan program apa yang dibuat, jam tayangnya, dan memastikan acaranya disukai penonton.', 'Mereka harus paham selera audiens dan memantau rating program. Cocok buat kamu yang suka dunia media, kreatif, dan bisa memimpin tim. Biasanya lulusan S1 komunikasi atau broadcasting dengan pengalaman di industri media.'),
  ('Casting Director', 'Casting director mencari dan memilih pemain yang paling cocok untuk film, serial, atau iklan. Mereka mengadakan audisi, menilai akting, dan mengusulkan pemain kepada sutradara dan produser.', 'Pekerjaannya membutuhkan mata yang jeli dan jaringan luas di dunia hiburan. Cocok buat kamu yang suka film, pandai menilai orang, dan senang berjejaring. Banyak yang memulai sebagai asisten casting.'),
  ('Technical Director Siaran', 'Technical director siaran mengendalikan peralatan teknis saat acara televisi ditayangkan, terutama saat siaran langsung. Mereka berpindah gambar antar kamera, mengatur grafis, dan memastikan siaran tanpa gangguan.', 'Saat siaran langsung, keputusan harus diambil dalam hitungan detik. Cocok buat kamu yang tenang di bawah tekanan dan suka teknologi media. Biasanya lulusan D3 atau S1 broadcasting atau teknik elektro.'),
  ('Music Director dan Komposer', 'Music director dan komposer menciptakan musik untuk lagu, film, iklan, atau game, sekaligus memimpin para musisi saat tampil atau rekaman. Mereka menentukan aransemen dan nuansa musiknya.', 'Banyak komposer sekarang bekerja dari studio rumah dengan software musik. Cocok buat kamu yang suka musik, paham teori musik, dan bisa memainkan alat musik. Biasanya lulusan S1 musik, tapi karya dan pengalaman paling menentukan.'),
  ('Penyiar Radio / Presenter TV', 'Penyiar radio dan presenter TV membawakan acara, membaca berita, mewawancarai tamu, atau memandu acara hiburan. Mereka menjadi wajah dan suara yang dikenal pendengar dan penonton.', 'Selain suara dan penampilan, mereka harus cepat berpikir dan bisa berimprovisasi. Sekarang banyak juga yang merambah podcast dan YouTube. Cocok buat kamu yang percaya diri, komunikatif, dan suka tampil.'),
  ('Jurnalis / Wartawan', 'Jurnalis meliput peristiwa dan menulis berita untuk media cetak, online, atau televisi. Mereka mewawancarai narasumber, mengecek fakta, dan menyajikan informasi yang akurat untuk publik.', 'Pekerjaannya dinamis, sering di lapangan, dan dikejar tenggat waktu. Jurnalis yang baik berperan penting menjaga masyarakat tetap mendapat informasi yang benar. Cocok buat kamu yang kritis, berani bertanya, dan suka menulis.'),
  ('PR Specialist / Humas', 'PR specialist atau humas membangun dan menjaga citra baik sebuah organisasi di mata publik. Mereka menulis siaran pers, berhubungan dengan media, mengelola acara, dan menangani krisis reputasi.', 'Saat ada isu negatif tentang perusahaan, humas yang pertama bergerak. Cocok buat kamu yang komunikatif, pandai menulis, dan tenang menghadapi situasi sulit. Biasanya lulusan S1 komunikasi atau hubungan masyarakat.'),
  ('Redaktur / Editor', 'Redaktur atau editor menyunting naskah supaya enak dibaca, akurat, dan layak terbit. Mereka memeriksa isi, gaya bahasa, dan fakta di berita, buku, atau konten online.', 'Di media, redaktur juga memutuskan berita mana yang dimuat dan di mana posisinya. Cocok buat kamu yang teliti, suka membaca, dan peka terhadap bahasa. Biasanya lulusan S1 bahasa, sastra, jurnalistik, atau komunikasi.'),
  ('Penulis', 'Penulis membuat tulisan untuk berbagai keperluan, seperti novel, artikel, naskah film, konten website, atau copywriting iklan. Mereka menyampaikan ide dan cerita lewat kata-kata.', 'Banyak penulis bekerja freelance dan menulis untuk berbagai klien sekaligus. Kemampuan riset dan menyesuaikan gaya tulisan sangat penting. Cocok buat kamu yang suka membaca, menulis, dan punya banyak cerita di kepala.'),
  ('Pencipta Lirik / Lyricist', 'Pencipta lirik menulis kata-kata untuk lagu, dari lagu pop, jingle iklan, sampai soundtrack film. Mereka merangkai kata yang pas dengan melodi dan bisa menyentuh perasaan pendengar.', 'Banyak lyricist bekerja sama dengan komposer, produser, dan penyanyi. Royalti dari lagu yang populer bisa jadi sumber penghasilan jangka panjang. Cocok buat kamu yang puitis, suka musik, dan pandai bermain kata.'),
  ('Penerjemah / Interpreter', 'Penerjemah mengalihbahasakan tulisan, sedangkan interpreter menerjemahkan ucapan secara langsung, misalnya di rapat atau konferensi internasional. Keduanya harus menyampaikan makna dengan akurat.', 'Bukan sekadar mengganti kata, mereka juga harus paham budaya dan konteks. Untuk dokumen resmi, kamu bisa menjadi penerjemah tersumpah. Cocok buat kamu yang menguasai lebih dari satu bahasa dan teliti.'),
  ('Teknisi Audio Video', 'Teknisi audio video memasang dan merawat peralatan audio visual, seperti sound system, proyektor, layar LED, dan mikrofon di ruang rapat, aula, atau acara. Mereka memastikan semuanya berfungsi saat dibutuhkan.', 'Saat acara berlangsung, mereka siaga kalau tiba-tiba suara hilang atau layar mati. Cocok buat kamu yang suka utak-atik perangkat elektronik. Biasanya lulusan SMK atau D3 elektronika atau multimedia.'),
  ('Teknisi Broadcast', 'Teknisi broadcast mengoperasikan dan merawat peralatan siaran radio dan televisi, seperti kamera studio, mixer, pemancar, dan sistem transmisi. Mereka menjaga siaran tetap mengudara tanpa gangguan.', 'Pekerjaannya bisa di studio maupun di lokasi siaran luar ruangan. Cocok buat kamu yang suka teknologi media dan teliti. Biasanya lulusan D3 broadcasting, elektronika, atau teknik telekomunikasi.'),
  ('Sound Engineer', 'Sound engineer merekam, mencampur, dan mengolah suara supaya terdengar jernih dan enak didengar. Mereka bekerja di studio rekaman, konser, produksi film, atau podcast.', 'Telinga yang tajam sama pentingnya dengan keahlian mengoperasikan alat. Cocok buat kamu yang suka musik dan teknologi audio. Banyak yang belajar lewat kursus audio engineering atau D3 multimedia, ditambah banyak praktik.'),
  ('Lighting Technician', 'Lighting technician mengatur pencahayaan untuk panggung, konser, film, atau acara. Mereka memasang lampu, mengatur warna dan arah cahaya, dan mengoperasikannya selama acara.', 'Pencahayaan yang tepat bisa mengubah suasana pertunjukan sepenuhnya. Pekerjaannya sering malam hari dan di lokasi acara. Cocok buat kamu yang suka dunia hiburan, tidak takut ketinggian, dan paham dasar kelistrikan.'),
  ('Fotografer', 'Fotografer mengabadikan momen dan objek lewat foto untuk berbagai kebutuhan, seperti pernikahan, produk, fashion, berita, atau karya seni. Mereka mengatur cahaya, komposisi, dan mengedit hasilnya.', 'Banyak fotografer bekerja freelance atau membuka studio sendiri. Portofolio dan jaringan klien adalah kunci sukses di bidang ini. Cocok buat kamu yang punya mata jeli dan suka bercerita lewat gambar.'),
  ('Cameraman / Videographer', 'Cameraman atau videographer merekam video untuk film, iklan, berita, konten media sosial, atau dokumentasi acara. Mereka mengatur angle kamera, gerakan, dan pencahayaan supaya gambar terlihat menarik.', 'Permintaan konten video terus naik, jadi peluang kerjanya makin banyak, termasuk freelance. Cocok buat kamu yang suka film, kreatif, dan tidak keberatan membawa peralatan berat. Portofolio video sangat menentukan.'),
  ('Video Editor', 'Video editor menyunting rekaman mentah menjadi video yang utuh dan menarik. Mereka memotong adegan, menyusun alur cerita, menambahkan musik, efek, dan teks.', 'Hasil kerjanya bisa berupa film, iklan, video YouTube, sampai konten TikTok. Software yang sering dipakai antara lain Premiere Pro, DaVinci Resolve, dan CapCut. Cocok buat kamu yang sabar, kreatif, dan peka terhadap ritme.'),
  ('Chiropractor', 'Chiropractor menangani keluhan pada tulang belakang, sendi, dan otot tanpa obat atau operasi. Mereka memakai teknik tekanan dan penyesuaian tangan untuk mengurangi nyeri dan memperbaiki postur.', 'Pasiennya banyak yang mengeluh sakit punggung, leher, atau cedera olahraga. Cocok buat kamu yang tertarik kesehatan, peduli pada orang, dan kuat secara fisik. Pendidikannya biasanya ditempuh di luar negeri karena masih jarang di Indonesia.'),
  ('Dokter Gigi', 'Dokter gigi memeriksa, merawat, dan mengobati masalah gigi dan mulut, seperti gigi berlubang, karang gigi, atau gusi bengkak. Mereka juga mengedukasi pasien cara merawat gigi dengan benar.', 'Banyak dokter gigi membuka praktik sendiri atau bekerja di klinik dan rumah sakit. Cocok buat kamu yang teliti, terampil dengan tangan, dan tertarik di bidang kesehatan. Pendidikannya S1 kedokteran gigi ditambah program profesi.'),
  ('Dokter Gigi Spesialis Bedah Mulut', 'Dokter gigi spesialis bedah mulut menangani operasi di area mulut, rahang, dan wajah, seperti mencabut gigi bungsu yang tumbuh miring, memperbaiki patah rahang, atau mengangkat kista.', 'Pekerjaannya butuh ketelitian tinggi dan tangan yang sangat terampil. Cocok buat kamu yang tertarik pada kedokteran gigi dan tidak takut tindakan bedah. Jalurnya dokter gigi lalu melanjutkan pendidikan spesialis bedah mulut.'),
  ('Dokter Gigi Spesialis Ortodonti', 'Dokter gigi spesialis ortodonti merapikan susunan gigi dan rahang dengan kawat gigi, aligner bening, atau alat lainnya. Hasil kerjanya bisa bikin senyum lebih rapi dan gigitan lebih nyaman.', 'Perawatannya bisa berlangsung bertahun-tahun, jadi hubungan baik dengan pasien sangat penting. Cocok buat kamu yang teliti, sabar, dan punya rasa estetika. Jalurnya dokter gigi lalu melanjutkan pendidikan spesialis ortodonti.'),
  ('Dokter Gigi Spesialis Prostodonsia', 'Dokter gigi spesialis prostodonsia membuat dan memasang gigi tiruan, seperti gigi palsu, mahkota gigi, jembatan, dan implan. Mereka membantu pasien bisa mengunyah dan tersenyum dengan percaya diri lagi.', 'Pasiennya banyak yang sudah lanjut usia atau kehilangan gigi karena kecelakaan. Cocok buat kamu yang teliti, suka detail, dan punya rasa estetika. Jalurnya dokter gigi lalu melanjutkan pendidikan spesialis prostodonsia.'),
  ('Ahli Gizi', 'Ahli gizi menyusun pola makan sehat sesuai kebutuhan seseorang, misalnya untuk pasien diabetes, ibu hamil, atlet, atau anak yang kekurangan gizi. Mereka memberi konsultasi dan menyusun menu.', 'Mereka bisa bekerja di rumah sakit, puskesmas, katering, sampai membuka konsultasi online. Cocok buat kamu yang tertarik makanan dan kesehatan, serta senang membantu orang hidup lebih sehat. Biasanya lulusan S1 gizi plus profesi dietisien.'),
  ('Optometris', 'Optometris memeriksa penglihatan, mengukur kebutuhan kacamata atau lensa kontak, dan mendeteksi gangguan mata sejak dini. Mereka banyak bekerja di optik, klinik mata, atau rumah sakit.', 'Dengan makin banyak orang yang menatap layar seharian, kebutuhan pemeriksaan mata terus naik. Cocok buat kamu yang teliti dan suka melayani orang. Biasanya lulusan D3 atau D4 optometri/refraksi optisi.'),
  ('Apoteker', 'Apoteker menyiapkan obat, memastikan dosisnya tepat, dan menjelaskan cara memakainya kepada pasien. Mereka juga mengecek apakah ada obat yang tidak boleh diminum bersamaan.', 'Apoteker bisa bekerja di apotek, rumah sakit, industri farmasi, atau BPOM. Cocok buat kamu yang suka kimia, teliti, dan peduli kesehatan orang. Pendidikannya S1 farmasi dilanjutkan program profesi apoteker.'),
  ('Terapis Okupasi', 'Terapis okupasi membantu pasien kembali mandiri melakukan aktivitas sehari-hari, seperti makan, berpakaian, atau menulis. Pasiennya bisa anak berkebutuhan khusus, korban stroke, atau orang yang baru cedera.', 'Terapinya dilakukan lewat latihan dan kegiatan yang disesuaikan dengan kondisi tiap orang. Cocok buat kamu yang sabar, kreatif, dan senang melihat orang lain berkembang. Biasanya lulusan D3 atau D4 okupasi terapi.'),
  ('Fisioterapis', 'Fisioterapis membantu pasien memulihkan gerak tubuh lewat latihan, pijatan, dan alat terapi. Pasiennya bisa korban kecelakaan, penderita stroke, atlet cedera, atau lansia yang sulit bergerak.', 'Mereka bekerja di rumah sakit, klinik, klub olahraga, atau membuka praktik sendiri. Cocok buat kamu yang suka bergerak, sabar, dan peduli pada pemulihan orang lain. Biasanya lulusan D3 atau S1 fisioterapi.'),
  ('Radiografer Radioterapi', 'Radiografer radioterapi menjalankan terapi radiasi untuk pasien kanker sesuai rencana dari dokter. Mereka mengatur posisi pasien, mengoperasikan mesin radiasi, dan memastikan dosisnya tepat.', 'Pekerjaannya menuntut ketelitian tinggi sekaligus empati, karena pasien sering dalam kondisi berat. Cocok buat kamu yang tertarik pada teknologi medis dan ingin membantu pasien kanker. Biasanya lulusan D3 atau D4 radiologi.'),
  ('Terapis Respirasi', 'Terapis respirasi menangani pasien dengan gangguan pernapasan, seperti asma, PPOK, atau pasien yang memakai ventilator di ICU. Mereka mengatur alat bantu napas dan melatih pasien bernapas lebih baik.', 'Pandemi COVID-19 menunjukkan betapa pentingnya peran ini di rumah sakit. Cocok buat kamu yang tenang di situasi darurat dan tertarik dunia medis. Biasanya lulusan D3 keperawatan atau fisioterapi dengan pelatihan khusus.'),
  ('Terapis Wicara', 'Terapis wicara melatih orang yang kesulitan berbicara, berbahasa, atau menelan. Pasiennya bisa anak yang terlambat bicara, orang yang gagap, atau pasien stroke yang kehilangan kemampuan bicara.', 'Terapinya dilakukan lewat latihan rutin yang disesuaikan dengan kondisi tiap pasien. Cocok buat kamu yang sabar, telaten, dan senang berkomunikasi. Biasanya lulusan D3 atau D4 terapi wicara.'),
  ('Terapis Seni', 'Terapis seni memakai kegiatan seni seperti menggambar, melukis, atau membuat kerajinan untuk membantu orang mengungkapkan perasaan dan pulih dari masalah emosional atau trauma.', 'Pasiennya bisa anak-anak, remaja, korban bencana, atau orang dengan gangguan mental. Cocok buat kamu yang suka seni sekaligus peduli pada kesehatan mental. Biasanya lulusan S1 psikologi atau seni dengan pelatihan khusus terapi seni.'),
  ('Terapis Musik', 'Terapis musik memakai musik, seperti bernyanyi, bermain alat musik, atau mendengarkan lagu, untuk membantu pemulihan fisik dan emosi pasien. Terapinya bisa untuk anak autis, lansia, atau pasien rehabilitasi.', 'Mereka merancang sesi musik sesuai tujuan terapi tiap pasien. Cocok buat kamu yang bisa bermain musik dan peduli pada kesehatan orang lain. Biasanya lulusan S1 musik atau psikologi dengan pelatihan khusus terapi musik.'),
  ('Dokter Hewan', 'Dokter hewan memeriksa, mengobati, dan merawat kesehatan hewan, dari kucing dan anjing peliharaan, ternak, sampai satwa liar. Mereka juga melakukan vaksinasi, operasi, dan mencegah penyakit menular dari hewan.', 'Mereka bisa bekerja di klinik hewan, peternakan, kebun binatang, atau dinas peternakan. Cocok buat kamu yang sayang binatang dan tertarik ilmu kesehatan. Pendidikannya S1 kedokteran hewan dilanjutkan program profesi.'),
  ('Perawat', 'Perawat merawat pasien dan memantau kondisinya setiap hari di rumah sakit, klinik, atau puskesmas. Mereka memberikan obat, mengganti perban, mengecek tanda vital, dan mendampingi pasien selama dirawat.', 'Perawat sering jadi orang yang paling dekat dengan pasien. Peluang kerjanya luas, termasuk ke luar negeri seperti Jepang dan Timur Tengah. Cocok buat kamu yang peduli, sabar, dan kuat mental. Pendidikannya S1 keperawatan plus profesi Ners.'),
  ('Perawat Perawatan Akut', 'Perawat perawatan akut merawat pasien dengan kondisi serius yang butuh penanganan cepat, misalnya setelah operasi, serangan jantung, atau kecelakaan. Mereka memantau kondisi pasien dengan ketat.', 'Pekerjaannya cepat dan penuh tekanan, tapi sangat menentukan keselamatan pasien. Cocok buat kamu yang sigap, tenang, dan tidak gampang panik. Biasanya perawat lulusan Ners yang punya pelatihan tambahan di bidang perawatan akut.'),
  ('Perawat Spesialis Jiwa', 'Perawat spesialis jiwa merawat pasien dengan gangguan kesehatan jiwa, seperti depresi, skizofrenia, atau kecanduan. Mereka mendampingi pasien, memberi obat, dan membantu proses pemulihan.', 'Kesadaran soal kesehatan mental yang makin tinggi membuat peran ini makin dibutuhkan. Cocok buat kamu yang empatik, sabar, dan tidak mudah menghakimi. Biasanya perawat Ners yang melanjutkan ke pendidikan spesialis keperawatan jiwa.'),
  ('Perawat Kritis', 'Perawat kritis merawat pasien yang kondisinya paling berat di ruang ICU. Mereka memantau alat-alat seperti ventilator dan monitor jantung, serta harus siap bertindak cepat setiap saat.', 'Pekerjaannya sangat menantang secara fisik dan mental, tapi bisa menyelamatkan nyawa. Cocok buat kamu yang teliti, sigap, dan tahan tekanan. Biasanya perawat Ners dengan pelatihan khusus perawatan intensif.'),
  ('Perawat Klinis Spesialis', 'Perawat klinis spesialis memberikan perawatan tingkat lanjut sesuai bidang keahliannya, misalnya perawatan luka, kanker, atau anak. Mereka juga membimbing perawat lain dan ikut menyusun standar perawatan.', 'Mereka menjadi rujukan saat ada kasus perawatan yang sulit. Cocok buat kamu yang ingin mendalami satu bidang keperawatan dan suka membimbing orang. Biasanya perawat Ners yang melanjutkan ke pendidikan S2 atau spesialis keperawatan.'),
  ('Penata Anestesi', 'Penata anestesi membantu dokter anestesi selama operasi. Mereka menyiapkan obat dan alat bius, memantau kondisi pasien selama dibius, dan mendampingi pasien saat sadar kembali.', 'Peran mereka sangat penting untuk keselamatan pasien di ruang operasi. Cocok buat kamu yang teliti, tenang, dan tertarik pada dunia medis. Biasanya lulusan D4 keperawatan anestesiologi.'),
  ('Audiolog', 'Audiolog memeriksa dan menangani gangguan pendengaran pada anak maupun dewasa. Mereka melakukan tes pendengaran, menentukan jenis gangguan, dan merekomendasikan alat bantu dengar yang tepat.', 'Pemeriksaan pada bayi dan anak sangat penting supaya gangguan pendengaran tidak menghambat kemampuan bicaranya. Cocok buat kamu yang teliti dan sabar. Biasanya lulusan S1 atau D4 audiologi.'),
  ('Dokter Spesialis Anestesi', 'Dokter spesialis anestesi memastikan pasien tidak merasakan sakit dan tetap aman selama operasi. Mereka menentukan jenis dan dosis obat bius, lalu memantau napas, jantung, dan tekanan darah pasien sampai operasi selesai.', 'Mereka juga menangani pasien kritis di ICU dan nyeri berat. Cocok buat kamu yang tenang, teliti, dan bisa mengambil keputusan cepat. Jalurnya S1 kedokteran, profesi dokter, lalu pendidikan spesialis anestesiologi.'),
  ('Dokter Spesialis Jantung', 'Dokter spesialis jantung mendiagnosis dan mengobati penyakit jantung dan pembuluh darah, seperti serangan jantung, darah tinggi, dan gangguan irama jantung. Mereka membaca hasil EKG dan pemeriksaan jantung lainnya.', 'Penyakit jantung termasuk penyebab kematian terbesar di Indonesia, jadi peran mereka sangat penting. Cocok buat kamu yang tekun belajar dan siap dengan pendidikan panjang. Jalurnya dokter umum lalu spesialis jantung dan pembuluh darah.'),
  ('Dokter Spesialis Kulit & Kelamin', 'Dokter spesialis kulit dan kelamin mengobati masalah pada kulit, rambut, kuku, dan penyakit menular seksual. Mulai dari jerawat, eksim, alergi kulit, sampai perawatan estetika.', 'Banyak juga yang berpraktik di klinik kecantikan selain di rumah sakit. Cocok buat kamu yang teliti dan tertarik pada kesehatan sekaligus penampilan. Jalurnya dokter umum lalu melanjutkan pendidikan spesialis dermatologi dan venereologi.'),
  ('Dokter Spesialis Kedokteran Gawat Darurat', 'Dokter spesialis kedokteran gawat darurat menangani pasien yang butuh pertolongan segera, seperti korban kecelakaan, serangan jantung, atau keracunan. Mereka bekerja di IGD dan harus mengambil keputusan dalam hitungan menit.', 'Setiap hari bisa berbeda dan penuh kejutan. Cocok buat kamu yang tenang di bawah tekanan, cepat berpikir, dan suka tantangan. Jalurnya dokter umum lalu melanjutkan pendidikan spesialis emergensi.'),
  ('Dokter Umum', 'Dokter umum adalah dokter pertama yang kamu temui saat sakit. Mereka memeriksa, mendiagnosis, dan mengobati berbagai penyakit umum, serta merujuk pasien ke spesialis kalau diperlukan.', 'Mereka bisa bekerja di puskesmas, klinik, rumah sakit, atau membuka praktik sendiri. Cocok buat kamu yang peduli kesehatan orang, tekun belajar, dan siap menghadapi pendidikan yang cukup panjang. Jalurnya S1 kedokteran lalu program profesi dokter.'),
  ('Dokter Spesialis Penyakit Dalam', 'Dokter spesialis penyakit dalam mendiagnosis dan mengobati penyakit pada organ dalam orang dewasa, seperti diabetes, hipertensi, gangguan ginjal, dan penyakit lambung. Banyak pasiennya punya lebih dari satu penyakit.', 'Mereka sering jadi koordinator perawatan pasien yang kondisinya rumit. Cocok buat kamu yang suka berpikir analitis dan memecahkan teka-teki medis. Jalurnya dokter umum lalu melanjutkan pendidikan spesialis penyakit dalam.'),
  ('Dokter Spesialis Saraf', 'Dokter spesialis saraf menangani gangguan otak dan sistem saraf, seperti stroke, epilepsi, migrain, dan parkinson. Mereka memakai pemeriksaan seperti CT scan dan MRI untuk menemukan penyebabnya.', 'Otak adalah organ paling rumit, jadi bidang ini penuh tantangan dan terus berkembang. Cocok buat kamu yang penasaran cara kerja otak dan tekun belajar. Jalurnya dokter umum lalu melanjutkan pendidikan spesialis neurologi.'),
  ('Dokter Spesialis Obgyn', 'Dokter spesialis obgyn menangani kehamilan, persalinan, dan kesehatan reproduksi wanita. Mereka memantau ibu hamil, membantu persalinan normal maupun caesar, serta mengobati gangguan kandungan.', 'Mereka ikut menyaksikan dan membantu lahirnya kehidupan baru setiap hari. Jam kerjanya tidak menentu karena persalinan bisa terjadi kapan saja. Jalurnya dokter umum lalu melanjutkan pendidikan spesialis obstetri dan ginekologi.'),
  ('Dokter Spesialis Anak', 'Dokter spesialis anak merawat kesehatan bayi, anak, dan remaja. Mereka memantau tumbuh kembang, memberi imunisasi, dan mengobati penyakit yang sering dialami anak-anak.', 'Mereka juga harus pandai berkomunikasi dengan orang tua yang sering khawatir. Cocok buat kamu yang sayang anak-anak, sabar, dan ceria. Jalurnya dokter umum lalu melanjutkan pendidikan spesialis anak.'),
  ('Dokter Spesialis Patologi', 'Dokter spesialis patologi memeriksa jaringan, darah, dan sampel tubuh lainnya di laboratorium untuk menegakkan diagnosis. Merekalah yang memastikan apakah sebuah benjolan itu kanker atau bukan.', 'Mereka jarang bertemu pasien langsung, tapi hasil pemeriksaannya menentukan pengobatan yang dipilih dokter lain. Cocok buat kamu yang teliti dan suka bekerja di laboratorium. Jalurnya dokter umum lalu pendidikan spesialis patologi.'),
  ('Dokter Spesialis Jiwa', 'Dokter spesialis jiwa atau psikiater mendiagnosis dan mengobati gangguan kesehatan jiwa, seperti depresi, gangguan cemas, bipolar, dan skizofrenia. Mereka bisa memberi terapi bicara sekaligus obat.', 'Kesadaran masyarakat soal kesehatan mental terus naik, jadi kebutuhan psikiater juga meningkat. Cocok buat kamu yang empatik, pendengar yang baik, dan tidak mudah menghakimi. Jalurnya dokter umum lalu pendidikan spesialis kedokteran jiwa.'),
  ('Dokter Spesialis Radiologi', 'Dokter spesialis radiologi membaca hasil rontgen, CT scan, MRI, dan USG untuk membantu dokter lain menegakkan diagnosis. Mereka bisa melihat masalah di dalam tubuh tanpa harus membedah.', 'Bidang ini sangat berhubungan dengan teknologi, termasuk pemakaian AI untuk membaca gambar medis. Cocok buat kamu yang teliti dan suka teknologi. Jalurnya dokter umum lalu melanjutkan pendidikan spesialis radiologi.'),
  ('Dokter Spesialis Alergi Imunologi', 'Dokter spesialis alergi imunologi menangani alergi dan gangguan sistem kekebalan tubuh, seperti alergi makanan, asma alergi, lupus, dan gangguan imun lainnya. Mereka mencari pemicu alergi dan cara mengendalikannya.', 'Kasus alergi dan autoimun makin sering ditemukan, tapi jumlah spesialisnya masih sedikit. Cocok buat kamu yang suka memecahkan kasus rumit. Jalurnya dokter umum, spesialis penyakit dalam atau anak, lalu subspesialis alergi imunologi.'),
  ('Dokter Spesialis Urologi', 'Dokter spesialis urologi mengobati gangguan saluran kemih pada pria dan wanita, serta organ reproduksi pria. Contohnya batu ginjal, infeksi saluran kemih, dan pembesaran prostat.', 'Mereka menangani pasien lewat obat maupun tindakan operasi, termasuk operasi dengan teknologi minimal sayatan. Cocok buat kamu yang tertarik pada bedah. Jalurnya dokter umum lalu melanjutkan pendidikan spesialis urologi.'),
  ('Dokter Spesialis Rehab Medik', 'Dokter spesialis rehabilitasi medik membantu pasien memulihkan fungsi tubuh setelah cedera, stroke, operasi, atau penyakit lama. Mereka menyusun program terapi bersama fisioterapis dan terapis okupasi.', 'Tujuannya supaya pasien bisa kembali beraktivitas semandiri mungkin. Cocok buat kamu yang sabar dan senang melihat perkembangan pasien dari waktu ke waktu. Jalurnya dokter umum lalu pendidikan spesialis kedokteran fisik dan rehabilitasi.'),
  ('Dokter Spesialis Kedokteran Komunitas', 'Dokter spesialis kedokteran komunitas fokus menjaga kesehatan masyarakat luas, bukan hanya satu pasien. Mereka merancang program pencegahan penyakit, menganalisis data kesehatan, dan menangani wabah.', 'Mereka banyak bekerja di dinas kesehatan, puskesmas, atau lembaga kesehatan internasional. Cocok buat kamu yang peduli pada dampak besar dan suka data. Jalurnya dokter umum lalu pendidikan spesialis kedokteran komunitas.'),
  ('Dokter Spesialis Kedokteran Olahraga', 'Dokter spesialis kedokteran olahraga menangani cedera akibat olahraga dan membantu atlet menjaga kebugaran. Mereka juga memberi saran latihan yang aman untuk masyarakat umum.', 'Mereka bisa bekerja di klub olahraga, tim nasional, rumah sakit, atau pusat kebugaran. Cocok buat kamu yang suka olahraga dan tertarik pada kedokteran. Jalurnya dokter umum lalu melanjutkan pendidikan spesialis kedokteran olahraga.'),
  ('Dokter Spesialis Mata', 'Dokter spesialis mata mendiagnosis dan mengobati penyakit mata, seperti katarak, glaukoma, dan gangguan retina. Mereka juga melakukan operasi mata, termasuk operasi katarak dan LASIK.', 'Gangguan penglihatan sangat umum di Indonesia, terutama katarak pada lansia. Cocok buat kamu yang teliti dan punya tangan terampil. Jalurnya dokter umum lalu melanjutkan pendidikan spesialis oftalmologi.'),
  ('Dokter Spesialis Ortopedi', 'Dokter spesialis ortopedi menangani cedera dan penyakit tulang, sendi, dan otot, seperti patah tulang, cedera lutut, dan pengapuran sendi. Banyak penanganannya berupa operasi.', 'Pasiennya mulai dari korban kecelakaan, atlet, sampai lansia. Pekerjaannya cukup menguras fisik karena operasi bisa berjam-jam. Cocok buat kamu yang tertarik pada bedah dan tubuh manusia. Jalurnya dokter umum lalu pendidikan spesialis ortopedi.'),
  ('Dokter Spesialis Bedah Anak', 'Dokter spesialis bedah anak melakukan operasi pada bayi, anak, dan remaja, misalnya kelainan bawaan lahir, usus buntu, atau hernia. Tubuh anak berbeda dari orang dewasa, jadi butuh keahlian khusus.', 'Jumlah dokter bedah anak di Indonesia masih sedikit, jadi kebutuhannya besar. Cocok buat kamu yang sayang anak, terampil, dan tahan tekanan. Jalurnya dokter umum, lalu pendidikan spesialis bedah anak yang cukup panjang.'),
  ('Akupunkturis', 'Akupunkturis mengobati keluhan kesehatan dengan menusukkan jarum halus ke titik-titik tertentu di tubuh. Teknik ini dipakai untuk meredakan nyeri, sakit kepala, atau membantu pemulihan.', 'Mereka bisa berpraktik mandiri, di klinik, atau di rumah sakit yang punya layanan pengobatan tradisional. Cocok buat kamu yang tertarik pada pengobatan alternatif dan teliti. Biasanya lulusan D3 akupunktur.'),
  ('Terapis Gigi dan Mulut', 'Terapis gigi dan mulut membersihkan karang gigi, memberi edukasi cara merawat gigi, dan membantu mencegah masalah gigi sejak dini. Mereka sering bekerja di puskesmas, klinik gigi, atau program kesehatan sekolah.', 'Peran mereka penting karena masalah gigi masih banyak dialami anak-anak Indonesia. Cocok buat kamu yang teliti dan senang mengedukasi orang. Biasanya lulusan D3 kesehatan gigi atau terapi gigi dan mulut.'),
  ('Ahli Teknologi Laboratorium Medik', 'Ahli teknologi laboratorium medik menganalisis sampel darah, urine, dan cairan tubuh lain untuk membantu dokter menegakkan diagnosis. Mereka juga memastikan peralatan lab bekerja akurat.', 'Hasil pemeriksaannya menentukan pengobatan yang diberikan ke pasien, jadi ketelitian sangat penting. Cocok buat kamu yang suka biologi, kimia, dan kerja laboratorium. Biasanya lulusan D4 atau S1 teknologi laboratorium medis.'),
  ('Teknisi Laboratorium Medik', 'Teknisi laboratorium medik memeriksa sampel darah dan cairan tubuh di laboratorium klinik atau rumah sakit. Mereka mengambil darah pasien, menjalankan alat pemeriksaan, dan mencatat hasilnya.', 'Pemeriksaan seperti cek gula darah, kolesterol, dan darah lengkap dikerjakan oleh mereka. Cocok buat kamu yang teliti, tidak takut darah, dan suka kerja laboratorium. Biasanya lulusan D3 teknologi laboratorium medis.'),
  ('Teknisi Histologi', 'Teknisi histologi menyiapkan potongan jaringan tubuh yang sangat tipis supaya bisa diperiksa di bawah mikroskop oleh dokter patologi. Sampelnya bisa dari biopsi atau operasi.', 'Pekerjaannya butuh tangan yang sangat terampil dan teliti karena kualitas preparat menentukan ketepatan diagnosis. Cocok buat kamu yang suka biologi dan kerja laboratorium. Biasanya lulusan D3 teknologi laboratorium medis.'),
  ('Teknisi Kardiovaskular', 'Teknisi kardiovaskular membantu dokter memeriksa dan menangani masalah jantung. Mereka mengoperasikan alat seperti EKG, treadmill test, dan membantu tindakan pemasangan ring jantung di ruang kateterisasi.', 'Pekerjaannya menuntut ketelitian dan ketenangan, karena pasien jantung bisa tiba-tiba kritis. Cocok buat kamu yang tertarik pada teknologi medis. Biasanya lulusan D3 keperawatan atau teknik elektromedik dengan pelatihan khusus.'),
  ('Sonografer', 'Sonografer mengoperasikan alat USG untuk melihat bagian dalam tubuh pasien, seperti janin dalam kandungan, jantung, atau organ perut. Gambar yang dihasilkan lalu dibaca oleh dokter.', 'Pekerjaannya butuh tangan yang terampil dan pemahaman anatomi tubuh. Cocok buat kamu yang tertarik pada teknologi medis dan suka bertemu pasien. Biasanya lulusan D3 radiologi dengan pelatihan tambahan di bidang ultrasonografi.'),
  ('Radiografer Kedokteran Nuklir', 'Radiografer kedokteran nuklir mengoperasikan alat pencitraan yang memakai zat radioaktif dalam dosis aman untuk melihat fungsi organ, seperti tiroid, jantung, atau tulang.', 'Mereka menyiapkan pasien, memberikan zat radioaktif sesuai prosedur, dan memastikan keselamatan radiasi. Cocok buat kamu yang teliti dan tertarik pada teknologi medis canggih. Biasanya lulusan D3 atau D4 radiologi.'),
  ('Radiografer', 'Radiografer mengoperasikan alat rontgen dan CT scan untuk memotret bagian dalam tubuh pasien. Mereka mengatur posisi pasien, memilih pengaturan alat, dan memastikan paparan radiasi seaman mungkin.', 'Hasil foto mereka dibaca oleh dokter radiologi untuk menegakkan diagnosis. Cocok buat kamu yang tertarik pada teknologi medis dan teliti. Biasanya lulusan D3 radiologi, dan peluang kerjanya ada di hampir semua rumah sakit.'),
  ('Radiografer MRI', 'Radiografer MRI mengoperasikan mesin MRI yang memakai magnet kuat untuk menghasilkan gambar detail bagian dalam tubuh, seperti otak, tulang belakang, dan sendi.', 'Mereka harus memastikan pasien aman, misalnya tidak membawa benda logam ke ruang MRI. Cocok buat kamu yang teliti, tenang, dan tertarik pada teknologi medis canggih. Biasanya lulusan D3 atau D4 radiologi dengan pelatihan MRI.'),
  ('Petugas Gawat Darurat', 'Petugas gawat darurat memberi pertolongan pertama di keadaan darurat, seperti kecelakaan, orang pingsan, atau korban bencana. Mereka menstabilkan kondisi korban sebelum dibawa ke rumah sakit.', 'Mereka bisa bekerja di rumah sakit, tim SAR, perusahaan, atau layanan ambulans. Cocok buat kamu yang sigap, berani, dan tetap tenang dalam situasi genting. Pelatihan dan sertifikasi pertolongan pertama menjadi bekal utama.'),
  ('Paramedis', 'Paramedis memberi pertolongan medis darurat di lapangan dan di dalam ambulans. Mereka menangani korban kecelakaan, serangan jantung, atau kondisi kritis lainnya sampai pasien tiba di rumah sakit.', 'Pekerjaannya penuh adrenalin dan setiap detik sangat berharga. Cocok buat kamu yang sigap, kuat secara fisik dan mental, dan ingin menyelamatkan nyawa. Biasanya lulusan D3 keperawatan dengan pelatihan kegawatdaruratan.'),
  ('Teknisi Gizi', 'Teknisi gizi menyiapkan makanan pasien di rumah sakit sesuai diet yang sudah ditentukan ahli gizi, misalnya makanan rendah garam untuk pasien hipertensi atau makanan lunak setelah operasi.', 'Mereka juga mengawasi kebersihan dapur dan memastikan porsi serta waktu makan pasien tepat. Cocok buat kamu yang suka memasak dan tertarik pada kesehatan. Biasanya lulusan D3 gizi.'),
  ('Tenaga Teknis Kefarmasian', 'Tenaga teknis kefarmasian membantu apoteker menyiapkan, meracik, dan menyerahkan obat kepada pasien. Mereka juga mengelola stok obat dan memastikan penyimpanannya sesuai aturan.', 'Mereka bisa bekerja di apotek, rumah sakit, puskesmas, atau industri farmasi. Cocok buat kamu yang teliti, rapi, dan tertarik pada obat-obatan. Biasanya lulusan D3 farmasi.'),
  ('Instrumentator Bedah', 'Instrumentator bedah menyiapkan dan menyerahkan alat-alat bedah kepada dokter selama operasi. Mereka harus hafal ratusan jenis alat dan tahu kapan alat itu dibutuhkan.', 'Mereka juga memastikan semua alat steril dan tidak ada yang tertinggal di tubuh pasien. Cocok buat kamu yang teliti, cekatan, dan tahan berdiri lama. Biasanya perawat lulusan D3 keperawatan dengan pelatihan kamar operasi.'),
  ('Paramedis Veteriner', 'Paramedis veteriner membantu dokter hewan memeriksa, merawat, dan mengobati hewan. Mereka bisa bertugas di klinik hewan, peternakan, atau dinas peternakan untuk vaksinasi dan pengendalian penyakit ternak.', 'Pekerjaannya sering di lapangan, terutama di daerah peternakan. Cocok buat kamu yang sayang binatang dan tidak takut kotor. Biasanya lulusan D3 kesehatan hewan atau paramedik veteriner.'),
  ('Perawat Vokasi (D3 Keperawatan)', 'Perawat vokasi memberi asuhan keperawatan dasar kepada pasien, seperti mengukur tanda vital, memberi obat, merawat luka, dan membantu kebutuhan sehari-hari pasien selama dirawat.', 'Mereka bekerja di rumah sakit, klinik, puskesmas, atau panti werdha. Peluang kerja ke luar negeri juga terbuka luas. Cocok buat kamu yang peduli, sabar, dan kuat secara fisik. Pendidikannya D3 keperawatan.'),
  ('Perekam Medis', 'Perekam medis mengelola rekam medis pasien supaya lengkap, rapi, dan mudah ditemukan saat dibutuhkan. Mereka juga mengurus kode diagnosis untuk klaim BPJS dan laporan rumah sakit.', 'Sekarang pekerjaannya banyak memakai sistem rekam medis elektronik. Cocok buat kamu yang teliti dan rapi, tapi lebih suka bekerja dengan data daripada langsung merawat pasien. Biasanya lulusan D3 rekam medis dan informasi kesehatan.'),
  ('Spesialis Alat Bantu Dengar', 'Spesialis alat bantu dengar memeriksa pendengaran, memilihkan alat bantu dengar yang sesuai, lalu menyetel dan merawatnya. Mereka membantu orang dengan gangguan pendengaran bisa mendengar lebih baik lagi.', 'Pasiennya banyak yang lansia, tapi ada juga anak-anak. Pekerjaannya gabungan kesehatan, teknologi, dan pelayanan. Cocok buat kamu yang sabar dan teliti. Biasanya lulusan D3 dengan pelatihan khusus audiometri.'),
  ('Teknisi Neurodiagnostik', 'Teknisi neurodiagnostik merekam aktivitas otak dan saraf dengan alat seperti EEG. Hasil rekamannya dipakai dokter saraf untuk mendiagnosis epilepsi, gangguan tidur, atau masalah saraf lainnya.', 'Mereka memasang elektroda di kepala pasien dan memastikan rekaman berjalan baik. Cocok buat kamu yang teliti, sabar, dan tertarik pada teknologi medis. Biasanya lulusan D3 keperawatan atau elektromedik dengan pelatihan khusus.'),
  ('Petugas Layanan Pasien', 'Petugas layanan pasien membantu pasien mendapatkan layanan kesehatan yang dibutuhkan, seperti mengurus pendaftaran, jadwal dokter, rujukan, dan administrasi BPJS. Mereka jadi penghubung antara pasien dan rumah sakit.', 'Banyak pasien datang dalam keadaan cemas, jadi keramahan sangat penting. Cocok buat kamu yang komunikatif, sabar, dan suka membantu orang. Biasanya lulusan D3 administrasi rumah sakit atau kesehatan.'),
  ('Analis Informasi Kesehatan', 'Analis informasi kesehatan mengolah data kesehatan untuk mendukung layanan rumah sakit dan program kesehatan. Misalnya, menganalisis penyakit yang paling banyak diderita pasien atau tren kunjungan.', 'Hasil analisisnya membantu rumah sakit atau dinas kesehatan mengambil keputusan. Cocok buat kamu yang suka data dan tertarik pada dunia kesehatan. Biasanya lulusan D3 atau D4 rekam medis dan informasi kesehatan.'),
  ('Fisioterapis Olahraga', 'Fisioterapis olahraga membantu atlet pulih dari cedera dan mencegah cedera berulang. Mereka memberi terapi, latihan khusus, dan sering mendampingi tim saat bertanding.', 'Mereka bisa bekerja di klub sepak bola, tim nasional, pusat kebugaran, atau klinik olahraga. Cocok buat kamu yang suka olahraga dan tertarik pada pemulihan tubuh. Biasanya lulusan D3 atau S1 fisioterapi dengan pelatihan olahraga.'),
  ('Asisten Bedah', 'Asisten bedah membantu dokter bedah selama operasi, misalnya menahan jaringan, menjahit luka, dan memastikan area operasi tetap bersih dan terlihat jelas.', 'Pekerjaannya menuntut fokus tinggi dan bisa berlangsung berjam-jam. Cocok buat kamu yang cekatan, tenang, dan tertarik dengan dunia bedah. Biasanya perawat dengan pengalaman kamar operasi dan pelatihan tambahan.'),
  ('Bidan', 'Bidan mendampingi ibu sejak hamil, saat melahirkan, sampai merawat bayi baru lahir. Mereka juga memberi layanan KB, imunisasi, dan edukasi kesehatan ibu dan anak.', 'Di banyak desa, bidan menjadi tenaga kesehatan utama bagi ibu hamil. Mereka bisa bekerja di puskesmas, rumah sakit, atau membuka praktik mandiri. Cocok buat kamu yang peduli dan sigap. Biasanya lulusan D3 atau S1 kebidanan.'),
  ('Caregiver Lansia', 'Caregiver lansia merawat dan mendampingi orang lanjut usia dalam kegiatan sehari-hari, seperti makan, mandi, minum obat, dan berjalan. Mereka juga menjadi teman bicara yang menjaga semangat lansia.', 'Kebutuhannya terus naik, termasuk di luar negeri seperti Jepang dan Taiwan. Cocok buat kamu yang sabar, telaten, dan penyayang. Bisa dimulai dari lulusan SMA/SMK dengan pelatihan caregiver.'),
  ('Caregiver Pendamping Pribadi', 'Caregiver pendamping pribadi mendampingi dan merawat orang yang butuh bantuan sehari-hari, misalnya penyandang disabilitas atau orang yang sedang dalam masa pemulihan. Mereka membantu kebutuhan dasar dan aktivitas harian.', 'Pekerjaannya biasanya di rumah klien dengan jadwal yang disesuaikan. Cocok buat kamu yang sabar, peduli, dan bisa dipercaya. Bisa dimulai dari lulusan SMA/SMK dengan pelatihan perawatan dasar.'),
  ('Asisten Perawat', 'Asisten perawat membantu perawat merawat pasien sehari-hari, seperti memandikan, mengganti seprai, membantu makan, dan memindahkan pasien. Mereka membuat pasien lebih nyaman selama dirawat.', 'Pekerjaan ini bisa jadi langkah awal untuk menjadi perawat. Cocok buat kamu yang peduli, kuat secara fisik, dan tidak keberatan dengan pekerjaan yang melelahkan. Biasanya lulusan D3 atau pelatihan asisten keperawatan.'),
  ('Asisten Fisioterapis', 'Asisten fisioterapis membantu fisioterapis menjalankan latihan pemulihan pasien. Mereka menyiapkan alat terapi, mendampingi pasien berlatih, dan mencatat perkembangannya.', 'Pekerjaannya aktif bergerak dan banyak berinteraksi dengan pasien. Cocok buat kamu yang suka membantu orang dan tertarik di bidang kesehatan. Biasanya lulusan D3 fisioterapi atau pelatihan terkait.'),
  ('Terapis Pijat', 'Terapis pijat memberi pijatan untuk meredakan pegal, mengurangi stres, dan menyegarkan tubuh. Mereka bekerja di spa, hotel, pusat kebugaran, atau melayani panggilan ke rumah.', 'Pekerjaannya cukup menguras tenaga, tapi bisa memberi kepuasan karena membuat orang merasa lebih baik. Cocok buat kamu yang punya tangan terampil dan suka melayani. Keterampilannya bisa dipelajari lewat kursus bersertifikat.'),
  ('Asisten Dokter Gigi', 'Asisten dokter gigi membantu dokter gigi selama pemeriksaan dan perawatan. Mereka menyiapkan alat, menyedot air liur pasien, mensterilkan peralatan, dan mengatur jadwal pasien.', 'Pekerjaannya cocok untukmu yang ingin bekerja di dunia kesehatan tanpa pendidikan yang terlalu panjang. Cocok buat kamu yang teliti, cekatan, dan ramah. Biasanya lulusan D3 kesehatan gigi atau pelatihan asisten dokter gigi.'),
  ('Petugas Sterilisasi Alat Medis', 'Petugas sterilisasi alat medis membersihkan dan mensterilkan alat-alat medis supaya aman dipakai lagi, terutama alat bedah. Mereka mengoperasikan mesin sterilisasi seperti autoklaf.', 'Pekerjaannya di balik layar, tapi sangat penting untuk mencegah infeksi pada pasien. Cocok buat kamu yang teliti, rapi, dan disiplin mengikuti prosedur. Bisa dimulai dari lulusan SMA/SMK dengan pelatihan khusus.'),
  ('Asisten Apotek', 'Asisten apotek melayani pembeli di apotek, menyiapkan obat sesuai resep di bawah pengawasan apoteker, dan menata stok obat. Mereka juga menjawab pertanyaan ringan soal produk kesehatan.', 'Banyak apotek jaringan besar yang membuka lowongan ini secara rutin. Cocok buat kamu yang teliti, ramah, dan tertarik pada obat-obatan. Bisa dimulai dari lulusan SMK farmasi.'),
  ('Asisten Dokter Hewan', 'Asisten dokter hewan membantu dokter hewan di klinik, seperti memegang hewan saat diperiksa, membersihkan kandang, memberi makan hewan yang dirawat, dan menyiapkan alat.', 'Pekerjaan ini pas untukmu yang sayang binatang dan ingin bekerja dekat dengan mereka setiap hari. Cocok buat kamu yang sabar dan tidak takut kotor. Bisa dimulai dari lulusan SMA/SMK.'),
  ('Teknisi Endoskopi', 'Teknisi endoskopi membantu pemeriksaan saluran cerna dengan alat endoskopi, yaitu selang kecil berkamera yang dimasukkan ke tubuh pasien. Mereka menyiapkan alat, membantu dokter, dan membersihkan alat setelah dipakai.', 'Alat endoskopi sangat mahal dan sensitif, jadi perawatannya harus hati-hati. Cocok buat kamu yang teliti dan tertarik pada teknologi medis. Biasanya perawat atau tenaga kesehatan dengan pelatihan khusus endoskopi.'),
  ('Makeup Artist (MUA)', 'Makeup artist merias wajah untuk berbagai acara, seperti pernikahan, wisuda, pemotretan, film, atau panggung. Mereka menyesuaikan riasan dengan bentuk wajah, warna kulit, dan tema acara.', 'Banyak MUA membangun bisnis sendiri dan mempromosikan karyanya lewat Instagram dan TikTok. Cocok buat kamu yang kreatif, suka kecantikan, dan teliti. Keterampilannya bisa dipelajari lewat kursus makeup profesional.'),
  ('Staff Rental', 'Staff rental melayani penyewaan barang atau kendaraan, seperti mobil, motor, alat pesta, atau kamera. Mereka mengurus pemesanan, mengecek kondisi barang, dan menjelaskan aturan sewa kepada pelanggan.', 'Pekerjaannya banyak berinteraksi dengan pelanggan dan butuh ketelitian saat serah terima barang. Cocok buat kamu yang ramah, teliti, dan bisa dipercaya. Bisa dimulai dari lulusan SMA/SMK.'),
  ('Sales Iklan', 'Sales iklan menjual ruang iklan di media, seperti televisi, radio, website, media sosial, atau papan reklame. Mereka mencari pengiklan, menawarkan paket, dan menjaga hubungan baik dengan klien.', 'Penghasilannya sering ditambah komisi dari target penjualan. Cocok buat kamu yang supel, persuasif, dan paham dunia media. Biasanya lulusan S1 komunikasi, pemasaran, atau manajemen.'),
  ('Agen Asuransi', 'Agen asuransi menawarkan produk asuransi, seperti asuransi jiwa, kesehatan, atau pendidikan, dan membantu nasabah memilih polis yang sesuai kebutuhannya. Mereka juga membantu saat nasabah mengajukan klaim.', 'Penghasilannya banyak dari komisi, jadi semakin banyak nasabah, semakin besar pendapatan. Cocok buat kamu yang supel, jujur, dan suka bertemu orang. Kamu perlu lulus ujian lisensi agen dari asosiasi asuransi.'),
  ('Sales Sekuritas', 'Sales sekuritas menawarkan produk investasi pasar modal, seperti saham, obligasi, dan reksa dana, kepada nasabah. Mereka membantu nasabah membuka rekening dan memberi informasi soal pasar.', 'Minat anak muda berinvestasi saham terus naik, jadi peluangnya makin besar. Cocok buat kamu yang suka dunia investasi dan pandai berkomunikasi. Kamu perlu lisensi WPPE dari OJK untuk bisa bekerja di bidang ini.'),
  ('Staff Travel Agent', 'Staff travel agent membantu pelanggan merencanakan perjalanan, mulai dari memesan tiket pesawat, hotel, sampai paket tur. Mereka memberi saran destinasi dan mengurus dokumen perjalanan seperti visa.', 'Pekerjaannya banyak berhubungan dengan pelanggan dan sistem pemesanan. Cocok buat kamu yang suka traveling, ramah, dan teliti. Biasanya lulusan D3 pariwisata atau perhotelan.'),
  ('Technical Sales Representative', 'Technical sales representative menjual produk teknis, seperti mesin industri, alat kesehatan, atau software, dan menjelaskan cara kerjanya kepada klien. Mereka harus paham produknya secara mendalam.', 'Pekerjaannya gabungan antara kemampuan teknis dan kemampuan menjual. Cocok buat kamu yang punya latar teknik tapi suka bertemu orang dan bernegosiasi. Biasanya lulusan S1 teknik atau sains.'),
  ('Sales Solar Panel', 'Sales solar panel menjual sistem panel surya kepada rumah tangga, kantor, atau pabrik. Mereka menghitung kebutuhan listrik pelanggan, menjelaskan penghematan, dan menawarkan paket pemasangan.', 'Minat orang beralih ke energi surya terus naik, jadi pasar ini sedang tumbuh. Cocok buat kamu yang peduli lingkungan, suka bertemu orang, dan paham dasar kelistrikan. Biasanya lulusan D3 atau S1 teknik.'),
  ('Sales Representative', 'Sales representative menawarkan produk perusahaan ke pelanggan, baik toko, perusahaan, maupun perorangan. Mereka mencari pelanggan baru, menjaga hubungan dengan pelanggan lama, dan mengejar target penjualan.', 'Penghasilannya biasanya ditambah komisi dan bonus. Pekerjaannya banyak di luar kantor. Cocok buat kamu yang supel, pantang menyerah, dan suka tantangan target. Banyak perusahaan menerima lulusan dari berbagai jurusan.'),
  ('Broker Properti', 'Broker properti menjembatani transaksi jual beli dan sewa rumah, apartemen, ruko, atau tanah. Mereka mencarikan pembeli, mengatur survei lokasi, dan membantu negosiasi sampai transaksi selesai.', 'Penghasilannya dari komisi transaksi, jadi bisa sangat besar kalau berhasil menjual properti mahal. Cocok buat kamu yang supel, persuasif, dan tahan banting. Lisensi broker properti dibutuhkan untuk bekerja secara resmi.'),
  ('Agen Properti', 'Agen properti membantu pemilik memasarkan, menyewakan, dan menjual properti. Mereka memotret properti, memasang iklan online, menerima calon pembeli, dan menemani saat survei lokasi.', 'Banyak agen bekerja di bawah kantor broker besar sambil membangun jaringan klien sendiri. Cocok buat kamu yang suka bertemu orang, aktif di media sosial, dan pandai meyakinkan. Bisa dimulai tanpa latar pendidikan khusus.'),
  ('Sales Engineer', 'Sales engineer menjual solusi teknis yang rumit, seperti sistem otomasi pabrik atau perangkat jaringan, dan menyesuaikannya dengan kebutuhan klien. Mereka sering membuat presentasi dan demo produk.', 'Mereka jadi jembatan antara tim teknis perusahaan dan klien. Penghasilannya umumnya tinggi karena menggabungkan keahlian teknik dan penjualan. Cocok buat kamu yang punya latar teknik dan suka berkomunikasi.'),
  ('Telemarketing', 'Telemarketing menawarkan produk atau layanan kepada calon pelanggan lewat telepon, misalnya kartu kredit, asuransi, atau paket internet. Mereka mengikuti naskah, menjawab pertanyaan, dan mencatat hasil panggilan.', 'Pekerjaan ini melatih kemampuan komunikasi dan mental pantang menyerah. Cocok buat kamu yang suaranya ramah, sabar, dan tidak mudah patah semangat saat ditolak. Bisa dimulai dari lulusan SMA/SMK.'),
  ('Teller', 'Teller bank melayani nasabah yang ingin menyetor, menarik, atau mentransfer uang di kantor bank. Mereka menghitung uang dengan teliti dan memastikan setiap transaksi tercatat dengan benar.', 'Pekerjaan ini sering jadi pintu masuk berkarier di dunia perbankan. Cocok buat kamu yang teliti, rapi, ramah, dan jujur. Biasanya bisa dimulai dari lulusan SMA/SMK atau D3, dan banyak bank membuka program rekrutmen rutin.'),
  ('Verifikator Kredit', 'Verifikator kredit memeriksa kebenaran data calon peminjam, seperti alamat, pekerjaan, dan penghasilan. Mereka bisa menelepon atau mendatangi langsung untuk memastikan datanya valid.', 'Hasil verifikasi mereka membantu bank atau perusahaan pembiayaan menghindari penipuan dan kredit macet. Cocok buat kamu yang teliti, jujur, dan tidak keberatan turun ke lapangan. Bisa dimulai dari lulusan SMA/SMK.'),
  ('Customer Service', 'Customer service menjawab pertanyaan dan menangani keluhan pelanggan, baik lewat telepon, chat, email, maupun langsung di kantor. Mereka berusaha menyelesaikan masalah supaya pelanggan tetap puas.', 'Hampir semua perusahaan butuh customer service, dari bank, e-commerce, sampai provider internet. Cocok buat kamu yang sabar, ramah, dan pintar berkomunikasi. Bisa dimulai dari lulusan SMA/SMK.'),
  ('Admin Kredit', 'Admin kredit mengurus dokumen dan administrasi pengajuan kredit di bank atau perusahaan pembiayaan. Mereka memeriksa kelengkapan berkas, menginput data ke sistem, dan menyiapkan dokumen perjanjian.', 'Pekerjaannya banyak di depan komputer dan butuh ketelitian tinggi. Cocok buat kamu yang rapi, teliti, dan suka pekerjaan administrasi. Biasanya lulusan D3 administrasi, akuntansi, atau perbankan.'),
  ('Admin Order', 'Admin order memproses pesanan pelanggan dari awal sampai barang terkirim. Mereka mencatat pesanan, mengecek stok, berkoordinasi dengan gudang, dan memastikan barang dikirim tepat waktu.', 'Peran ini sangat dibutuhkan di perusahaan distribusi dan toko online. Cocok buat kamu yang teliti, cepat, dan terbiasa pakai Excel atau sistem online. Bisa dimulai dari lulusan SMA/SMK.'),
  ('Staff Cargo', 'Staff cargo mengurus pengiriman barang lewat udara, laut, atau darat. Mereka menimbang barang, mengurus dokumen pengiriman, dan memastikan muatan tersusun dengan aman.', 'Pekerjaannya bisa di bandara, pelabuhan, atau gudang ekspedisi. Cocok buat kamu yang teliti, cekatan, dan tidak keberatan dengan pekerjaan fisik. Bisa dimulai dari lulusan SMA/SMK.'),
  ('Staff Freight Forwarding', 'Staff freight forwarding mengatur pengiriman barang antarnegara untuk klien, mulai dari memesan kapal atau pesawat, mengurus dokumen ekspor-impor, sampai urusan bea cukai.', 'Pekerjaannya banyak berkomunikasi dengan pihak luar negeri, jadi bahasa Inggris sangat membantu. Cocok buat kamu yang teliti, terorganisir, dan tertarik dunia perdagangan internasional. Bisa dimulai dari lulusan SMA/SMK.'),
  ('Kurir', 'Kurir mengantar paket dan dokumen ke penerima dengan cepat dan tepat waktu. Seiring maraknya belanja online, kurir menjadi salah satu pekerjaan yang paling dibutuhkan.', 'Pekerjaannya banyak di jalan, jadi butuh fisik yang kuat dan paham rute. Cocok buat kamu yang suka bergerak, bertanggung jawab, dan bisa mengatur waktu. Biasanya perlu SIM dan kendaraan sendiri.'),
  ('Dispatcher', 'Dispatcher mengatur jadwal dan rute armada atau petugas lapangan, misalnya kurir, sopir truk, atau teknisi. Mereka memastikan setiap tugas dikerjakan oleh orang yang tepat di waktu yang tepat.', 'Saat ada kendala di jalan, dispatcher yang mencari solusi dengan cepat. Cocok buat kamu yang terorganisir, tenang di bawah tekanan, dan pintar berkomunikasi. Bisa dimulai dari lulusan SMA/SMK.'),
  ('Petugas Pencatat Meter', 'Petugas pencatat meter mendatangi rumah dan gedung untuk mencatat angka meteran listrik, air, atau gas. Data yang mereka kumpulkan dipakai untuk menghitung tagihan pelanggan.', 'Pekerjaannya banyak berjalan dan berkendara di lapangan setiap hari. Cocok buat kamu yang teliti, jujur, dan suka bekerja di luar ruangan. Bisa dimulai dari lulusan SMA/SMK.'),
  ('Staff PPIC', 'Staff PPIC merencanakan jadwal produksi dan memastikan bahan baku tersedia tepat waktu. Mereka menghitung berapa banyak barang yang harus dibuat, kapan, dan bahan apa saja yang perlu dipesan.', 'Kalau perencanaannya meleset, pabrik bisa kehabisan bahan atau malah menumpuk stok. Cocok buat kamu yang teliti, suka Excel, dan bisa berpikir beberapa langkah ke depan. Bisa dimulai dari SMK, dan lulusan teknik industri banyak dicari.'),
  ('Staff Gudang', 'Staff gudang mengelola barang yang masuk, disimpan, dan keluar dari gudang. Mereka mengecek jumlah dan kondisi barang, menata penyimpanan, dan mencatat semuanya ke sistem.', 'Dengan pertumbuhan e-commerce, kebutuhan staff gudang terus naik. Pekerjaannya cukup fisik dan butuh ketelitian. Cocok buat kamu yang rapi, cekatan, dan bertanggung jawab. Bisa dimulai dari lulusan SMA/SMK.'),
  ('Teknisi Pemanas Air Surya', 'Teknisi pemanas air surya memasang dan merawat sistem pemanas air yang memakai energi matahari, biasanya di atap rumah, hotel, atau rumah sakit. Mereka memasang panel, pipa, dan tangki air panas.', 'Pekerjaannya banyak di atap dan butuh keterampilan pipa serta kelistrikan dasar. Cocok buat kamu yang suka kerja praktis dan peduli energi ramah lingkungan. Biasanya lulusan SMK atau D3 teknik mesin atau listrik.'),
  ('Instalator Panel Surya (PLTS)', 'Instalator panel surya memasang dan merawat panel surya di atap rumah, gedung, atau ladang PLTS. Mereka memasang rangka, panel, kabel, dan inverter sesuai desain, lalu mengecek sistem bekerja dengan baik.', 'Seiring pertumbuhan energi surya di Indonesia, kebutuhan instalator terus naik. Cocok buat kamu yang tidak takut ketinggian dan suka kerja lapangan. Bisa dimulai dari lulusan SMK listrik dengan sertifikasi instalasi PLTS.'),
  ('Auditor Energi', 'Auditor energi memeriksa pemakaian energi di gedung atau pabrik, lalu mencari cara untuk menghematnya. Mereka mengukur pemakaian listrik, mesin, dan AC, kemudian menyusun rekomendasi penghematan.', 'Rekomendasi mereka bisa memangkas tagihan listrik secara signifikan. Cocok buat kamu yang teliti, suka hitung-hitungan, dan peduli lingkungan. Biasanya lulusan D3 atau S1 teknik dengan sertifikasi auditor energi.'),
  ('Operator Alat Berat Tambang', 'Operator alat berat tambang mengemudikan alat besar seperti excavator, dump truck, atau bulldozer untuk menggali dan memindahkan hasil tambang. Satu alat bisa seukuran rumah.', 'Pekerjaannya di lokasi tambang dengan sistem kerja rotasi, dan gajinya cukup menarik. Cocok buat kamu yang berani, fokus, dan kuat secara fisik. Bisa dimulai dari lulusan SMA/SMK dengan pelatihan dan SIO operator alat berat.'),
  ('Blaster / Juru Ledak', 'Blaster atau juru ledak menyiapkan dan meledakkan bahan peledak untuk memecah batuan di area tambang atau proyek konstruksi. Semua dilakukan sesuai prosedur keselamatan yang sangat ketat.', 'Satu kesalahan kecil bisa berakibat fatal, jadi disiplin dan ketelitian adalah segalanya. Cocok buat kamu yang tenang, teliti, dan sangat patuh aturan. Kamu perlu pelatihan dan izin resmi sebagai juru ledak.'),
  ('Operator Alat Muat Tambang Bawah Tanah', 'Operator alat muat tambang bawah tanah mengoperasikan alat khusus untuk memuat dan mengangkut hasil tambang di terowongan bawah tanah. Ruang geraknya sempit dan kondisinya menantang.', 'Keselamatan menjadi prioritas utama di setiap shift. Cocok buat kamu yang tidak takut ruang tertutup, fokus, dan kuat secara fisik. Bisa dimulai dari lulusan SMA/SMK dengan pelatihan dan sertifikasi operator.'),
  ('Teknisi ATM', 'Teknisi ATM memasang, memperbaiki, dan merawat mesin ATM supaya selalu siap dipakai. Kalau ATM macet atau kartu tertelan, mereka yang datang untuk memperbaikinya.', 'Pekerjaannya banyak berpindah lokasi dari satu ATM ke ATM lain. Cocok buat kamu yang suka elektronik, teliti, dan bisa dipercaya karena bekerja dekat dengan uang. Biasanya lulusan SMK atau D3 elektronika.'),
  ('Teknisi Audio Visual', 'Teknisi audio visual memasang dan memperbaiki peralatan seperti speaker, proyektor, layar LED, dan sistem video conference di kantor, sekolah, atau tempat acara.', 'Mereka juga sering bertugas saat ada seminar atau konser untuk memastikan semua peralatan berjalan lancar. Cocok buat kamu yang suka elektronik dan teknologi. Biasanya lulusan SMK atau D3 elektronika.'),
  ('Aircraft Maintenance Engineer', 'Aircraft maintenance engineer memeriksa, merawat, dan memperbaiki pesawat supaya laik terbang. Mereka mengecek mesin, sistem hidrolik, kelistrikan, dan badan pesawat sesuai jadwal perawatan yang ketat.', 'Keselamatan ratusan penumpang bergantung pada hasil kerja mereka. Cocok buat kamu yang sangat teliti dan suka mesin. Kamu perlu pendidikan teknik pesawat udara dan lisensi AMEL dari Kementerian Perhubungan.'),
  ('Teknisi Body Repair', 'Teknisi body repair memperbaiki bodi kendaraan yang penyok atau tergores. Mereka mengetok, mendempul, mengamplas, lalu mengecat ulang sampai bodi kendaraan terlihat seperti baru.', 'Pekerjaannya butuh tangan terampil dan mata yang jeli terhadap warna. Banyak bekerja di bengkel resmi dan bengkel body repair. Cocok buat kamu yang suka otomotif dan kerja praktik. Bisa dimulai dari lulusan SMK otomotif.'),
  ('Teknisi Kaca Mobil', 'Teknisi kaca mobil memasang dan memperbaiki kaca kendaraan, seperti kaca depan yang retak, kaca samping yang pecah, atau pemasangan kaca film. Mereka memastikan kaca terpasang rapat dan aman.', 'Pekerjaannya butuh ketelitian dan kehati-hatian karena kaca mudah pecah. Cocok buat kamu yang suka otomotif dan kerja tangan. Bisa dimulai dari lulusan SMK otomotif dengan pelatihan di bengkel.'),
  ('Mekanik Mobil', 'Mekanik mobil memeriksa, merawat, dan memperbaiki mobil. Mulai dari ganti oli, servis rutin, sampai memperbaiki mesin, rem, atau sistem kelistrikan yang bermasalah.', 'Mobil sekarang makin canggih, jadi mekanik juga perlu paham alat diagnosis elektronik. Cocok buat kamu yang suka otomotif dan senang membongkar mesin. Bisa dimulai dari SMK otomotif, lalu berkembang lewat pelatihan di bengkel resmi.'),
  ('Mekanik Diesel', 'Mekanik diesel merawat dan memperbaiki mesin diesel pada truk, bus, generator, dan alat berat. Mesin diesel punya cara kerja yang berbeda dari mesin bensin, jadi butuh keahlian khusus.', 'Peluang kerjanya banyak di perusahaan transportasi, tambang, dan perkebunan. Cocok buat kamu yang suka mesin besar dan tidak takut kotor. Biasanya lulusan SMK atau D3 teknik mesin atau otomotif.'),
  ('Mekanik Alat Pertanian', 'Mekanik alat pertanian merawat dan memperbaiki traktor, mesin panen, pompa air, dan mesin pertanian lainnya. Mereka memastikan petani bisa bekerja tanpa terhambat mesin yang rusak.', 'Pekerjaannya sering di lapangan, mendatangi sawah atau perkebunan. Seiring modernisasi pertanian, kebutuhannya terus bertambah. Cocok buat kamu yang suka mesin dan tidak keberatan kerja di luar ruangan.'),
  ('Mekanik Alat Berat', 'Mekanik alat berat merawat dan memperbaiki excavator, bulldozer, crane, dan alat berat lainnya di proyek konstruksi atau tambang. Mereka memastikan alat tetap bekerja karena satu alat rusak bisa menghentikan proyek.', 'Pekerjaannya sering di lokasi terpencil dengan sistem rotasi, tapi gajinya cukup menarik. Cocok buat kamu yang suka mesin besar dan kuat secara fisik. Biasanya lulusan SMK atau D3 teknik alat berat.'),
  ('Teknisi Perawatan Gerbong Kereta Api', 'Teknisi perawatan gerbong kereta api memeriksa dan merawat gerbong supaya aman dipakai, seperti roda, rem, sambungan, dan sistem kelistrikan. Mereka bekerja di depo atau balai yasa.', 'Keselamatan penumpang kereta bergantung pada hasil kerja mereka. Cocok buat kamu yang teliti, suka mesin, dan tertarik pada kereta api. Bisa dimulai dari lulusan SMK teknik mesin atau listrik.'),
  ('Mekanik Mesin Kapal', 'Mekanik mesin kapal merawat dan memperbaiki mesin kapal, baik di kapal yang sedang berlayar maupun di galangan. Mereka memastikan mesin, pompa, dan sistem kelistrikan kapal berfungsi baik.', 'Pekerjaannya bisa membawamu berlayar ke berbagai tempat. Cocok buat kamu yang suka mesin dan tidak mabuk laut. Biasanya lulusan SMK pelayaran atau D3 teknika, ditambah sertifikat keahlian pelaut.'),
  ('Mekanik Motor', 'Mekanik motor memeriksa, merawat, dan memperbaiki sepeda motor. Mulai dari servis rutin, ganti oli, sampai memperbaiki mesin, kelistrikan, dan sistem injeksi.', 'Dengan jutaan motor di jalanan Indonesia, kebutuhan mekanik motor tidak pernah habis. Banyak yang akhirnya membuka bengkel sendiri. Cocok buat kamu yang suka otomotif dan kerja praktik. Bisa dimulai dari lulusan SMK otomotif.'),
  ('Mekanik Mesin Kecil', 'Mekanik mesin kecil memperbaiki mesin seperti genset, pompa air, mesin potong rumput, dan gergaji mesin. Mereka mendiagnosis kerusakan, mengganti komponen, dan menyetel mesin agar bekerja lagi.', 'Banyak yang membuka bengkel sendiri di lingkungan tempat tinggal. Cocok buat kamu yang suka membongkar mesin dan senang memperbaiki barang. Bisa dimulai dari lulusan SMK teknik mesin.'),
  ('Teknisi Maintenance Mesin', 'Teknisi maintenance mesin merawat dan memperbaiki mesin produksi di pabrik supaya tidak berhenti beroperasi. Mereka melakukan perawatan rutin dan bergerak cepat saat ada mesin yang rusak.', 'Kalau mesin berhenti, produksi ikut berhenti, jadi peran mereka sangat penting. Cocok buat kamu yang suka mesin, cekatan, dan bisa memecahkan masalah dengan cepat. Bisa dimulai dari lulusan SMK teknik mesin atau listrik.'),
  ('Teknisi Servis Kamera', 'Teknisi servis kamera memperbaiki dan menyetel kamera serta lensa, seperti lensa yang berjamur, tombol rusak, atau sensor yang bermasalah. Pekerjaannya membutuhkan tangan yang sangat hati-hati.', 'Pelanggannya fotografer profesional, videografer, sampai penggemar fotografi. Cocok buat kamu yang teliti, sabar, dan suka elektronik serta fotografi. Biasanya lulusan D3 elektronika dengan pelatihan khusus.'),
  ('Teknisi Servis Turbin Angin', 'Teknisi servis turbin angin merawat dan memperbaiki turbin pembangkit listrik tenaga angin. Mereka memanjat menara setinggi puluhan meter untuk memeriksa mesin, baling-baling, dan sistem kelistrikan.', 'Pekerjaannya menantang dan butuh keberanian di ketinggian. Seiring bertambahnya pembangkit tenaga angin, kebutuhannya ikut naik. Cocok buat kamu yang suka tantangan fisik dan teknik. Biasanya lulusan D3 teknik mesin atau listrik.'),
  ('Teknisi Perakitan Struktur Pesawat', 'Teknisi perakitan struktur pesawat merakit bagian-bagian badan pesawat, seperti sayap, rangka, dan kulit pesawat. Mereka memasang komponen dengan presisi tinggi sesuai gambar teknik.', 'Di Indonesia, pekerjaan ini ada di industri seperti PT Dirgantara Indonesia. Cocok buat kamu yang teliti, terampil, dan bangga ikut membangun pesawat. Bisa dimulai dari lulusan SMK teknik pesawat udara atau mesin.'),
  ('Operator Perakitan Elektronik', 'Operator perakitan elektronik merakit komponen elektronik di lini produksi pabrik, misalnya memasang komponen ke papan sirkuit, menyolder, dan menguji fungsi produk.', 'Produk yang dirakit bisa berupa HP, TV, komponen mobil, atau perangkat rumah tangga. Cocok buat kamu yang teliti, sabar, dan tangannya cekatan. Bisa dimulai dari lulusan SMA/SMK, dan banyak pabrik di kawasan industri membuka lowongan.'),
  ('Fitter Logam', 'Fitter logam memotong, membentuk, dan merakit komponen logam sesuai gambar teknik. Hasilnya bisa berupa rangka mesin, struktur baja, atau komponen kapal.', 'Pekerjaannya banyak memakai alat potong, gerinda, dan alat ukur presisi. Cocok buat kamu yang suka kerja tangan, teliti, dan bisa membaca gambar teknik. Bisa dimulai dari lulusan SMK teknik mesin atau pengelasan.'),
  ('Operator Laminasi Fiberglass', 'Operator laminasi fiberglass membuat produk dari fiberglass dengan teknik laminasi, seperti body kapal, tangki air, atau komponen kendaraan. Mereka melapisi cetakan dengan serat kaca dan resin lapis demi lapis.', 'Pekerjaannya butuh ketelitian supaya hasilnya kuat dan rapi, serta wajib memakai alat pelindung diri. Cocok buat kamu yang suka kerja tangan. Bisa dimulai dari lulusan SMA/SMK dengan pelatihan di tempat kerja.'),
  ('Operator Assembly', 'Operator assembly merakit komponen produk di lini produksi pabrik sesuai standar dan target harian. Produknya bisa berupa elektronik, otomotif, atau barang konsumsi.', 'Pekerjaannya berulang, jadi butuh fokus dan ketelitian supaya kualitas tetap terjaga. Cocok buat kamu yang cekatan dan disiplin. Bisa dimulai dari lulusan SMA/SMK, dan bisa naik jenjang ke leader atau supervisor.'),
  ('Baker / Pembuat Roti', 'Baker membuat roti, kue, dan pastry, dari mengukur bahan, menguleni adonan, memanggang, sampai menghias. Mereka bekerja di bakery, hotel, kafe, atau membuka usaha sendiri.', 'Jam kerjanya sering mulai dini hari supaya roti siap dijual pagi-pagi. Cocok buat kamu yang suka membuat kue, sabar, dan teliti menakar bahan. Bisa dimulai dari SMK tata boga atau kursus baking.'),
  ('Butcher / Pemotong Daging', 'Butcher memotong dan menyiapkan daging sesuai pesanan, seperti steak, daging giling, atau potongan khusus. Mereka paham bagian-bagian daging dan cara memotongnya dengan tepat.', 'Mereka bisa bekerja di supermarket, restoran, hotel, atau toko daging. Cocok buat kamu yang terampil memakai pisau, teliti, dan menjaga kebersihan. Bisa dimulai dari lulusan SMA/SMK dengan pelatihan di tempat kerja.'),
  ('Operator RPH & Butcher', 'Operator RPH dan butcher bekerja di rumah potong hewan untuk menyembelih hewan ternak dan mengolah karkasnya menjadi potongan daging. Semua dilakukan sesuai standar halal dan kebersihan.', 'Pekerjaannya cukup berat secara fisik dan butuh mental yang kuat. Cocok buat kamu yang terampil, disiplin, dan paham standar kebersihan pangan. Bisa dimulai dari lulusan SMA/SMK, dan sertifikasi juru sembelih halal sangat membantu.'),
  ('Operator Mesin Ekstrusi', 'Operator mesin ekstrusi mengoperasikan mesin yang membentuk plastik atau logam dengan cara mendorongnya melalui cetakan. Hasilnya bisa berupa pipa, kabel, profil aluminium, atau plastik lembaran.', 'Mereka mengatur suhu dan kecepatan mesin, serta mengecek kualitas hasil produksi. Cocok buat kamu yang teliti dan suka bekerja dengan mesin. Bisa dimulai dari lulusan SMA/SMK.'),
  ('Operator Mesin Bubut', 'Operator mesin bubut mengoperasikan mesin bubut untuk membentuk komponen logam, seperti poros, baut, atau komponen mesin, dengan cara memutar benda kerja dan memotongnya.', 'Hasilnya harus presisi sampai ukuran milimeter. Cocok buat kamu yang teliti, sabar, dan suka bekerja dengan mesin. Bisa dimulai dari lulusan SMK teknik pemesinan.'),
  ('Machinist / Operator Bubut', 'Machinist membuat komponen presisi dengan mesin bubut, frais, dan mesin perkakas lainnya. Mereka membaca gambar teknik, memilih alat potong, dan mengerjakan logam sampai ukurannya tepat.', 'Keahlian ini dibutuhkan di industri otomotif, pesawat, dan manufaktur. Cocok buat kamu yang teliti dan suka bekerja dengan mesin. Biasanya lulusan SMK atau D3 teknik mesin dengan pengalaman praktik yang banyak.'),
  ('Operator Tungku Peleburan Logam (Furnace)', 'Operator tungku peleburan logam mengoperasikan tungku bersuhu sangat tinggi untuk melebur besi, baja, aluminium, atau logam lain. Logam cair ini lalu dicetak menjadi berbagai produk.', 'Lingkungan kerjanya panas dan berisiko, jadi keselamatan kerja sangat penting. Cocok buat kamu yang kuat secara fisik, disiplin, dan patuh prosedur. Bisa dimulai dari lulusan SMA/SMK.'),
  ('Operator Injection Molding', 'Operator injection molding mengoperasikan mesin yang menyuntikkan plastik cair ke dalam cetakan untuk membuat produk seperti tutup botol, casing elektronik, atau komponen otomotif.', 'Mereka mengatur suhu, tekanan, dan waktu mesin, lalu mengecek apakah hasilnya cacat. Cocok buat kamu yang teliti dan suka bekerja dengan mesin. Bisa dimulai dari lulusan SMA/SMK.'),
  ('Tool & Die Maker', 'Tool and die maker membuat dan memperbaiki cetakan serta alat bantu produksi yang dipakai di pabrik. Cetakan ini dipakai untuk membuat ribuan produk yang sama persis.', 'Pekerjaannya butuh ketelitian sangat tinggi dan keahlian memakai berbagai mesin perkakas. Keahlian ini langka dan dihargai tinggi. Cocok buat kamu yang suka detail dan teknik. Biasanya lulusan SMK atau D3 teknik mesin.'),
  ('Welder / Juru Las', 'Welder atau juru las menyambung logam dengan teknik pengelasan, seperti SMAW, MIG, atau TIG. Hasil lasnya dipakai di konstruksi gedung, kapal, pipa migas, sampai rangka kendaraan.', 'Welder bersertifikat sangat dicari, termasuk untuk bekerja di luar negeri. Cocok buat kamu yang terampil, teliti, dan tidak takut panas. Bisa dimulai dari lulusan SMK teknik pengelasan ditambah sertifikasi las.'),
  ('Operator Mesin Las', 'Operator mesin las mengoperasikan mesin las otomatis atau robot las di lini produksi pabrik. Mereka menyiapkan benda kerja, mengatur mesin, dan mengecek kualitas hasil lasan.', 'Pekerjaannya banyak di pabrik otomotif dan manufaktur logam. Cocok buat kamu yang teliti dan suka bekerja dengan mesin. Bisa dimulai dari lulusan SMK teknik mesin atau pengelasan.'),
  ('Teknisi Prepress', 'Teknisi prepress menyiapkan file desain dan pelat cetak sebelum proses pencetakan dimulai. Mereka memastikan warna, ukuran, dan resolusi sudah tepat supaya hasil cetak sesuai harapan.', 'Kesalahan di tahap ini bisa bikin ribuan cetakan terbuang. Cocok buat kamu yang teliti, paham software desain, dan tertarik pada dunia percetakan. Biasanya lulusan D3 teknik grafika atau desain grafis.'),
  ('Operator Mesin Cetak', 'Operator mesin cetak mengoperasikan mesin cetak untuk mencetak buku, kemasan, brosur, atau label. Mereka mengatur tinta, kertas, dan mesin, lalu mengecek kualitas hasil cetakan.', 'Pekerjaannya butuh mata yang jeli terhadap warna dan detail. Cocok buat kamu yang teliti dan suka bekerja dengan mesin. Bisa dimulai dari lulusan SMK grafika atau teknik mesin.'),
  ('Operator Jahit', 'Operator jahit menjahit pakaian atau produk tekstil dengan mesin jahit di pabrik garmen. Biasanya setiap operator mengerjakan bagian tertentu, seperti lengan, kerah, atau jahitan samping.', 'Industri garmen menyerap banyak tenaga kerja di Indonesia. Cocok buat kamu yang teliti, cekatan, dan tahan duduk lama. Bisa dimulai dari lulusan SMA/SMK, dan pelatihan menjahit sering diberikan di tempat kerja.'),
  ('Penjahit Tangan', 'Penjahit tangan menjahit dan menyelesaikan pakaian secara manual, misalnya memasang kancing, menyulam, atau mengerjakan detail yang tidak bisa dilakukan mesin. Pekerjaan ini penting untuk pakaian berkualitas tinggi.', 'Keterampilan ini banyak dibutuhkan di butik, rumah mode, dan pembuatan kebaya atau baju adat. Cocok buat kamu yang sabar, teliti, dan suka kerajinan. Bisa dimulai dari lulusan SMK tata busana.'),
  ('Penjahit / Tailor', 'Penjahit atau tailor membuat dan mengubah pakaian sesuai ukuran pelanggan. Mereka mengukur badan, memotong kain, menjahit, sampai melakukan fitting supaya pakaian pas di badan.', 'Banyak penjahit membuka usaha sendiri dengan pelanggan setia. Cocok buat kamu yang teliti, kreatif, dan suka fashion. Bisa dimulai dari SMK tata busana atau kursus menjahit.'),
  ('Pattern Maker / Pembuat Pola', 'Pattern maker membuat pola pakaian yang menjadi acuan untuk memotong dan menjahit kain. Pola ini menentukan apakah pakaian akan pas di badan dan terlihat bagus.', 'Mereka bekerja dekat dengan desainer fashion untuk mewujudkan desain menjadi pakaian nyata. Sekarang banyak juga yang memakai software pola digital. Cocok buat kamu yang teliti dan paham ukuran tubuh. Biasanya lulusan D3 tata busana.'),
  ('Tukang Kayu / Mebel', 'Tukang kayu atau mebel membuat dan memperbaiki perabot serta produk dari kayu, seperti lemari, meja, kursi, atau kusen. Mereka mengukur, memotong, merakit, dan menghaluskan kayu.', 'Mebel Indonesia, seperti dari Jepara, terkenal sampai ke luar negeri. Banyak tukang kayu yang akhirnya membuka usaha furnitur sendiri. Cocok buat kamu yang terampil dan suka membuat sesuatu dengan tangan.'),
  ('Tukang Finishing Furniture', 'Tukang finishing furniture menghaluskan dan melapisi furnitur supaya rapi, mengkilap, dan awet. Mereka mengamplas, mendempul, lalu mengecat atau memberi pelitur pada kayu.', 'Tahap finishing sangat menentukan tampilan akhir dan harga jual furnitur. Cocok buat kamu yang sabar, teliti, dan punya mata jeli terhadap warna. Bisa dimulai dari lulusan SMA/SMK dengan pelatihan di bengkel mebel.'),
  ('Operator Pembangkit Listrik', 'Operator pembangkit listrik mengoperasikan dan memantau mesin di pembangkit listrik, seperti turbin, generator, dan boiler. Mereka memastikan listrik terus mengalir ke rumah dan industri.', 'Pekerjaannya biasanya dalam sistem shift karena pembangkit beroperasi 24 jam. Cocok buat kamu yang teliti, disiplin, dan tertarik pada kelistrikan. Bisa dimulai dari lulusan SMK teknik listrik atau mesin.'),
  ('Teknisi Pembangkit Listrik Tenaga Biomassa (PLTBm)', 'Teknisi pembangkit listrik tenaga biomassa mengoperasikan dan merawat pembangkit yang memakai bahan bakar dari limbah pertanian, seperti cangkang sawit, sekam padi, atau serbuk kayu.', 'Pembangkit seperti ini banyak berada di dekat perkebunan atau pabrik pengolahan. Cocok buat kamu yang peduli energi ramah lingkungan dan suka mesin. Bisa dimulai dari lulusan SMK teknik mesin atau listrik.'),
  ('Teknisi Pembangkit Listrik Tenaga Air (PLTA)', 'Teknisi pembangkit listrik tenaga air mengoperasikan dan merawat PLTA, yang memakai aliran air dari bendungan atau sungai untuk menggerakkan turbin. Mereka memastikan turbin, generator, dan pintu air bekerja baik.', 'Lokasi kerjanya biasanya di daerah pegunungan atau dekat bendungan. Cocok buat kamu yang suka mesin dan alam. Biasanya lulusan D3 teknik mesin atau listrik.'),
  ('Operator Boiler', 'Operator boiler mengoperasikan dan merawat boiler, yaitu mesin penghasil uap panas yang dipakai di pabrik, rumah sakit, atau pembangkit listrik. Mereka memantau suhu, tekanan, dan kualitas air.', 'Boiler bertekanan tinggi bisa berbahaya, jadi operator harus sangat disiplin. Di Indonesia, operator boiler wajib punya sertifikat dari Kemnaker. Cocok buat kamu yang teliti dan suka mesin. Biasanya lulusan SMK atau D3 teknik mesin.'),
  ('Operator Pengolahan Air dan Air Limbah', 'Operator pengolahan air dan air limbah mengoperasikan instalasi yang menjernihkan air untuk dipakai masyarakat atau mengolah limbah supaya aman dibuang ke lingkungan.', 'Mereka memantau mesin, menambahkan bahan kimia sesuai takaran, dan menguji kualitas air secara rutin. Cocok buat kamu yang peduli lingkungan dan teliti. Bisa dimulai dari lulusan SMK kimia atau teknik.'),
  ('Operator Pabrik Kimia', 'Operator pabrik kimia mengoperasikan peralatan produksi di pabrik kimia, seperti reaktor, pompa, dan tangki. Mereka mengatur suhu, tekanan, dan aliran bahan sesuai prosedur.', 'Lingkungan kerjanya punya risiko bahan kimia, jadi keselamatan kerja sangat ketat. Cocok buat kamu yang teliti, disiplin, dan suka kimia. Bisa dimulai dari lulusan SMK kimia industri atau teknik.'),
  ('Operator Kilang/Distribusi Gas', 'Operator kilang atau distribusi gas mengoperasikan fasilitas pengolahan dan penyaluran gas, seperti kompresor, pipa, dan stasiun distribusi. Mereka memastikan gas mengalir aman ke industri dan rumah tangga.', 'Pekerjaannya dalam sistem shift dan menuntut kedisiplinan tinggi karena gas mudah terbakar. Cocok buat kamu yang teliti dan patuh prosedur. Bisa dimulai dari lulusan SMK teknik dengan pelatihan migas.'),
  ('Operator Kilang Minyak', 'Operator kilang minyak mengoperasikan dan memantau peralatan di kilang yang mengolah minyak mentah menjadi bensin, solar, dan produk lainnya. Mereka memastikan proses berjalan aman dan sesuai target.', 'Pekerjaannya dalam sistem shift dan gajinya cukup menarik. Cocok buat kamu yang teliti, disiplin, dan tertarik pada industri energi. Bisa dimulai dari lulusan SMK teknik kimia atau mesin dengan pelatihan migas.'),
  ('Teknisi Pengolahan Biofuel', 'Teknisi pengolahan biofuel mengoperasikan proses produksi bahan bakar nabati, seperti biodiesel dari minyak sawit. Mereka memantau mesin, mencampur bahan, dan menguji kualitas bahan bakar yang dihasilkan.', 'Indonesia termasuk pelopor program biodiesel, jadi industri ini terus berkembang. Cocok buat kamu yang suka kimia dan peduli energi terbarukan. Bisa dimulai dari lulusan SMK kimia atau teknik.'),
  ('Operator Peralatan Proses Kimia', 'Operator peralatan proses kimia mengoperasikan mesin dan peralatan yang mengolah bahan kimia, seperti mixer, reaktor, dan alat penyaring. Mereka mengikuti prosedur ketat supaya produk sesuai standar.', 'Pekerjaannya ada di pabrik pupuk, cat, farmasi, atau plastik. Cocok buat kamu yang teliti, disiplin, dan suka kimia. Bisa dimulai dari lulusan SMK kimia industri.'),
  ('Operator Mixing', 'Operator mixing mencampur bahan baku sesuai formula produksi, misalnya adonan makanan, bahan kosmetik, atau cat. Takaran dan urutan pencampuran harus tepat supaya produk sesuai standar.', 'Kesalahan kecil bisa membuat satu batch produksi gagal. Cocok buat kamu yang teliti, disiplin, dan suka mengikuti prosedur. Bisa dimulai dari lulusan SMA/SMK.'),
  ('QC Inspector', 'QC inspector memeriksa produk supaya sesuai standar mutu sebelum dikirim ke pelanggan. Mereka mengecek ukuran, tampilan, dan fungsi produk, lalu memisahkan barang yang cacat.', 'Peran mereka melindungi nama baik perusahaan dari produk yang bermasalah. Cocok buat kamu yang teliti, jeli, dan tegas. Bisa dimulai dari lulusan SMA/SMK, dan bisa naik ke posisi QC supervisor.'),
  ('Operator Mesin CNC', 'Operator mesin CNC mengoperasikan mesin yang dikendalikan komputer untuk membuat komponen logam atau plastik dengan presisi sangat tinggi. Mereka memasang benda kerja, menjalankan program, dan mengecek hasilnya.', 'Keahlian CNC sangat dicari di industri otomotif, elektronik, dan manufaktur. Cocok buat kamu yang teliti dan suka teknologi mesin. Bisa dimulai dari lulusan SMK teknik pemesinan.'),
  ('Programmer Mesin CNC', 'Programmer mesin CNC membuat program yang mengatur gerakan mesin CNC berdasarkan gambar teknik. Mereka menentukan jalur potong, kecepatan, dan alat yang dipakai supaya hasilnya presisi.', 'Pekerjaannya gabungan antara teknik mesin dan pemrograman, memakai software CAD/CAM. Cocok buat kamu yang teliti dan suka komputer serta mesin. Biasanya lulusan SMK atau D3 teknik mesin dengan pengalaman operator CNC.'),
  ('Operator Molding Plastik', 'Operator molding plastik mengoperasikan mesin cetak plastik di lini produksi untuk membuat barang seperti ember, botol, atau komponen kendaraan. Mereka mengatur mesin dan mengecek hasil cetakan.', 'Pekerjaannya biasanya dalam sistem shift di pabrik. Cocok buat kamu yang teliti, cekatan, dan suka bekerja dengan mesin. Bisa dimulai dari lulusan SMA/SMK.'),
  ('Operator Conveyor', 'Operator conveyor mengoperasikan dan memantau sistem ban berjalan yang memindahkan barang di pabrik, gudang, atau bandara. Mereka memastikan aliran barang lancar dan tidak macet.', 'Kalau conveyor berhenti, seluruh proses bisa terhambat, jadi mereka harus sigap. Cocok buat kamu yang fokus, cekatan, dan bertanggung jawab. Bisa dimulai dari lulusan SMA/SMK.'),
  ('Operator Crane', 'Operator crane mengoperasikan crane untuk mengangkat dan memindahkan muatan berat di proyek konstruksi, pelabuhan, atau pabrik. Mereka harus sangat presisi karena muatan bisa berton-ton.', 'Pekerjaannya menuntut fokus penuh dan koordinasi dengan petugas di bawah. Cocok buat kamu yang tenang, teliti, dan tidak takut ketinggian. Kamu perlu pelatihan dan Surat Izin Operator (SIO) crane.'),
  ('Operator Kapal Keruk (Dredge)', 'Operator kapal keruk mengoperasikan kapal khusus yang mengeruk lumpur dan pasir di dasar sungai, pelabuhan, atau laut. Pekerjaan ini penting supaya jalur kapal tetap dalam dan aman dilalui.', 'Pekerjaannya di atas air dalam waktu lama dengan sistem kerja rotasi. Cocok buat kamu yang suka laut atau sungai dan tidak mabuk laut. Bisa dimulai dari lulusan SMK pelayaran atau teknik dengan pelatihan khusus.'),
  ('Operator Truk/Traktor Industri', 'Operator truk atau traktor industri mengemudikan forklift, truk, atau traktor untuk memindahkan barang di area pabrik, gudang, atau pelabuhan. Mereka memastikan barang sampai di tempat yang tepat dengan aman.', 'Pekerjaannya butuh konsentrasi tinggi karena area kerja sering ramai. Cocok buat kamu yang hati-hati dan bertanggung jawab. Bisa dimulai dari lulusan SMA/SMK dengan SIO forklift atau SIM yang sesuai.'),
  ('Petugas Gudang dan Pemenuhan Pesanan', 'Petugas gudang dan pemenuhan pesanan menyiapkan pesanan pelanggan dari gudang: mengambil barang dari rak, mengecek, mengemas, lalu menyerahkannya ke kurir. Pekerjaan ini jadi tulang punggung belanja online.', 'Saat musim promo, jumlah pesanan bisa melonjak berkali lipat. Cocok buat kamu yang cekatan, teliti, dan kuat secara fisik. Bisa dimulai dari lulusan SMA/SMK.'),
  ('Operator Pompa', 'Operator pompa mengoperasikan pompa untuk menyalurkan cairan atau gas, seperti air, minyak, atau bahan kimia, di pabrik, kilang, atau instalasi air. Mereka memantau tekanan dan aliran supaya tetap stabil.', 'Mereka juga melakukan perawatan ringan dan melaporkan kalau ada kebocoran atau kerusakan. Cocok buat kamu yang teliti dan suka bekerja dengan mesin. Bisa dimulai dari lulusan SMA/SMK.'),
  ('Room Attendant / Housekeeping', 'Room attendant membersihkan dan merapikan kamar tamu hotel sesuai standar, mulai dari mengganti seprai, membersihkan kamar mandi, sampai mengisi ulang perlengkapan. Mereka memastikan setiap tamu masuk ke kamar yang bersih dan nyaman.', 'Pekerjaannya cukup fisik dan dikejar waktu, terutama saat hotel penuh. Banyak juga peluang kerja di kapal pesiar dan hotel luar negeri. Cocok buat kamu yang rapi, cekatan, dan teliti. Bisa dimulai dari lulusan SMK perhotelan.'),
  ('Analis Laboratorium Lingkungan', 'Analis laboratorium lingkungan mengambil dan menguji sampel air, udara, tanah, dan limbah untuk mengetahui apakah tercemar. Hasil ujinya dipakai untuk memantau lingkungan dan memastikan pabrik mematuhi aturan.', 'Pekerjaannya gabungan kerja lapangan dan laboratorium. Cocok buat kamu yang suka kimia, teliti, dan peduli lingkungan. Biasanya lulusan D3 analis kimia atau teknik lingkungan.'),
  ('Tour Leader', 'Tour leader mendampingi rombongan wisata selama perjalanan, termasuk ke luar negeri. Mereka mengatur jadwal, mengurus check-in hotel dan bandara, serta memastikan semua peserta aman dan senang.', 'Pekerjaannya membawamu berkeliling ke banyak tempat, tapi tanggung jawabnya besar. Cocok buat kamu yang suka traveling, komunikatif, dan sigap menyelesaikan masalah. Kemampuan bahasa asing sangat membantu.'),
  ('Prajurit TNI', 'Prajurit TNI menjaga kedaulatan dan keamanan negara sebagai anggota Angkatan Darat, Laut, atau Udara. Selain latihan militer, mereka juga sering membantu masyarakat saat terjadi bencana.', 'Kehidupannya penuh disiplin, latihan fisik, dan siap ditugaskan ke berbagai daerah. Cocok buat kamu yang kuat secara fisik dan mental serta punya jiwa pengabdian. Jalurnya lewat seleksi tamtama, bintara, atau Akademi Militer.'),
  ('Pekerja Sosial', 'Pekerja sosial mendampingi orang dan keluarga yang menghadapi masalah sosial, seperti kemiskinan, kekerasan dalam rumah tangga, anak terlantar, atau disabilitas. Mereka membantu klien mendapatkan layanan yang dibutuhkan.', 'Pekerjaannya bisa di dinas sosial, rumah sakit, lembaga perlindungan anak, atau LSM. Cocok buat kamu yang empatik, sabar, dan ingin membuat perubahan nyata. Biasanya lulusan S1 kesejahteraan sosial atau pekerjaan sosial.'),
  ('Teknisi BTS & Perangkat Telekomunikasi', 'Teknisi BTS dan perangkat telekomunikasi memasang dan merawat perangkat di menara BTS dan sentral operator seluler. Berkat mereka, sinyal HP-mu tetap kuat di mana-mana.', 'Pekerjaannya sering memanjat menara tinggi dan berpindah ke berbagai lokasi, termasuk daerah terpencil. Cocok buat kamu yang berani di ketinggian dan suka teknologi. Biasanya lulusan D3 teknik telekomunikasi atau elektro.'),
  ('Jaksa', 'Jaksa menuntut perkara pidana atas nama negara di persidangan. Mereka mempelajari berkas dari penyidik, menyusun dakwaan, menghadirkan bukti dan saksi, lalu mengajukan tuntutan kepada hakim.', 'Jaksa bekerja di Kejaksaan dan bisa ditugaskan ke berbagai daerah. Cocok buat kamu yang tegas, kritis, dan berani berargumen. Jalurnya S1 hukum, lalu lolos seleksi CPNS Kejaksaan dan pendidikan pembentukan jaksa.'),
  ('Advokat / Pengacara', 'Advokat atau pengacara mewakili dan membela klien dalam perkara hukum, baik pidana, perdata, bisnis, maupun keluarga. Mereka memberi nasihat hukum, menyusun dokumen, dan beracara di pengadilan.', 'Banyak advokat bekerja di firma hukum atau membuka kantor sendiri. Cocok buat kamu yang pandai berbicara, kritis, dan suka berdebat. Jalurnya S1 hukum, lalu ikut pendidikan khusus profesi advokat, ujian, dan disumpah.'),
  ('Petugas Pemadam Kebakaran', 'Petugas pemadam kebakaran memadamkan api dan menyelamatkan korban dalam berbagai keadaan darurat, seperti kebakaran, banjir, atau orang terjebak. Mereka juga mengevakuasi hewan dan membantu penanganan bencana.', 'Pekerjaannya penuh risiko dan butuh fisik prima serta keberanian. Cocok buat kamu yang sigap, berani, dan ingin menolong orang. Bisa dimulai dari lulusan SMA/SMK lewat rekrutmen dinas pemadam kebakaran.'),
  ('Paralegal', 'Paralegal membantu advokat dalam pekerjaan hukum, seperti meriset aturan dan putusan, menyusun draf dokumen, serta menyiapkan berkas perkara. Mereka membuat kerja tim hukum lebih cepat dan rapi.', 'Pekerjaan ini bisa jadi jalan awal sebelum menjadi advokat. Banyak juga paralegal di lembaga bantuan hukum yang membantu masyarakat tidak mampu. Cocok buat kamu yang teliti dan suka membaca. Biasanya lulusan S1 hukum.'),
  ('Analis Kebijakan Publik', 'Analis kebijakan publik mengkaji masalah di masyarakat, seperti pendidikan, kesehatan, atau transportasi, lalu menyusun rekomendasi kebijakan untuk pemerintah. Mereka mengumpulkan data dan membandingkan berbagai solusi.', 'Mereka bisa bekerja di kementerian, lembaga think tank, atau organisasi internasional. Cocok buat kamu yang kritis, suka riset, dan peduli isu publik. Biasanya lulusan S1 administrasi publik, ekonomi, atau ilmu politik.'),
  ('Concierge', 'Concierge membantu tamu hotel dengan berbagai kebutuhan, seperti memesan restoran, tiket, transportasi, atau tur. Mereka juga memberi rekomendasi tempat menarik di sekitar hotel.', 'Mereka harus paham betul kota tempat mereka bekerja dan punya banyak kenalan. Cocok buat kamu yang ramah, banyak akal, dan senang membantu. Bisa dimulai dari lulusan SMK perhotelan, dan bahasa asing sangat membantu.'),
  ('Supervisor Keamanan', 'Supervisor keamanan memimpin regu satpam dan memastikan prosedur pengamanan berjalan. Mereka mengatur jadwal jaga, mengawasi patroli, dan mengambil keputusan saat terjadi insiden.', 'Mereka bekerja di gedung perkantoran, mal, pabrik, atau kawasan perumahan. Cocok buat kamu yang tegas, disiplin, dan bisa memimpin. Biasanya diraih setelah berpengalaman sebagai satpam dan lulus pelatihan Gada Madya.'),
  ('Environmental Engineer', 'Environmental engineer merancang sistem untuk menjaga lingkungan tetap bersih, seperti instalasi pengolahan limbah, sistem air bersih, dan pengendalian polusi udara. Mereka mencari solusi teknis untuk masalah lingkungan.', 'Pekerjaannya bisa di konsultan, pabrik, atau instansi pemerintah. Cocok buat kamu yang peduli lingkungan dan suka teknik. Biasanya lulusan S1 teknik lingkungan.'),
  ('Front Office / Resepsionis Hotel', 'Front office atau resepsionis hotel menyambut tamu, mengurus check-in dan check-out, menerima reservasi, dan menjawab pertanyaan tamu. Mereka adalah wajah pertama yang dilihat tamu saat datang.', 'Pekerjaannya dalam sistem shift karena hotel buka 24 jam. Cocok buat kamu yang ramah, rapi, dan percaya diri berkomunikasi. Bisa dimulai dari lulusan SMK perhotelan, dan bahasa Inggris sangat membantu.'),
  ('Konsultan Lingkungan (AMDAL)', 'Konsultan lingkungan menyusun kajian AMDAL dan dokumen lingkungan lain untuk proyek seperti pabrik, tambang, atau jalan tol. Mereka menilai dampak proyek terhadap lingkungan dan masyarakat sekitar.', 'Dokumen mereka menjadi syarat supaya proyek mendapat izin. Pekerjaannya gabungan survei lapangan, analisis data, dan menulis laporan. Cocok buat kamu yang peduli lingkungan dan teliti. Biasanya lulusan S1 teknik lingkungan atau biologi.'),
  ('Chef', 'Chef memimpin dapur di restoran, hotel, atau katering. Mereka merancang menu, menentukan resep dan standar rasa, mengatur bahan dan biaya, serta memimpin tim juru masak.', 'Jam kerjanya panjang dan dapur bisa sangat sibuk, tapi kreativitasmu bisa dinikmati banyak orang. Cocok buat kamu yang suka masak dan bisa memimpin tim. Banyak yang mulai dari SMK tata boga atau sekolah kuliner, lalu naik jenjang dari cook.'),
  ('Polisi', 'Polisi menjaga keamanan dan ketertiban masyarakat sebagai anggota Polri. Tugasnya beragam, dari mengatur lalu lintas, berpatroli, menerima laporan warga, sampai menyelidiki tindak kejahatan.', 'Polisi bisa ditempatkan di berbagai daerah dan bidang, seperti lalu lintas, reserse, atau Brimob. Cocok buat kamu yang disiplin, tegas, dan kuat secara fisik. Jalurnya lewat seleksi bintara, tamtama, atau Akademi Kepolisian.'),
  ('Pemandu Wisata (Tour Guide)', 'Pemandu wisata memandu wisatawan berkeliling dan menjelaskan sejarah, budaya, serta cerita di balik tempat yang dikunjungi. Mereka membuat perjalanan jadi lebih seru dan bermakna.', 'Indonesia punya ribuan destinasi wisata, jadi peluangnya luas, terutama di daerah wisata seperti Bali dan Yogyakarta. Cocok buat kamu yang suka bercerita dan bertemu orang baru. Lisensi pemandu dan bahasa asing sangat membantu.'),
  ('Manajer Hotel', 'Manajer hotel memimpin seluruh operasional hotel, mulai dari layanan kamar, restoran, keuangan, sampai tim karyawan. Mereka memastikan tamu puas dan hotel berjalan menguntungkan.', 'Posisi ini biasanya diraih setelah bertahun-tahun bekerja di berbagai bagian hotel. Cocok buat kamu yang suka memimpin, ramah, dan bisa mengambil keputusan. Biasanya lulusan S1 perhotelan atau pariwisata.'),
  ('Manajer Program NGO', 'Manajer program NGO memimpin program sosial atau kemanusiaan di lembaga nonprofit, misalnya program pendidikan, kesehatan, atau bantuan bencana. Mereka merencanakan kegiatan, mengelola dana, dan memimpin tim lapangan.', 'Mereka juga menyusun laporan untuk donor dan mengukur dampak program. Cocok buat kamu yang peduli isu sosial, terorganisir, dan suka memimpin. Biasanya lulusan S1 dari berbagai jurusan, dengan pengalaman di dunia sosial.'),
  ('Fasilitator Pemberdayaan Masyarakat', 'Fasilitator pemberdayaan masyarakat mendampingi warga desa atau komunitas merencanakan dan menjalankan program pembangunan, seperti usaha bersama, air bersih, atau pengelolaan dana desa.', 'Pekerjaannya banyak di lapangan, tinggal dekat dengan warga, dan mendengar kebutuhan mereka. Cocok buat kamu yang suka bergaul, sabar, dan ingin membawa perubahan dari bawah. Biasanya lulusan S1 dari berbagai jurusan sosial.'),
  ('Hakim', 'Hakim memeriksa, mengadili, dan memutus perkara di pengadilan. Mereka mendengarkan argumen dari semua pihak, menilai bukti, lalu menjatuhkan putusan berdasarkan hukum dan keadilan.', 'Putusan hakim berdampak besar pada hidup orang, jadi integritas dan keadilan adalah segalanya. Cocok buat kamu yang bijak, objektif, dan berpendirian teguh. Jalurnya S1 hukum, lalu lolos seleksi calon hakim di Mahkamah Agung.'),
  ('Satpam / Security Officer', 'Satpam menjaga keamanan gedung, kawasan, atau acara. Mereka berjaga di pos, berpatroli, memeriksa tamu, dan bertindak cepat kalau ada kejadian mencurigakan atau keadaan darurat.', 'Hampir semua gedung, perumahan, dan pabrik membutuhkan satpam. Cocok buat kamu yang disiplin, waspada, dan sigap. Bisa dimulai dari lulusan SMA/SMK dengan pelatihan Gada Pratama yang menjadi syarat resmi.'),
  ('Teknisi Fiber Optik', 'Teknisi fiber optik memasang dan memperbaiki kabel fiber optik yang membawa internet cepat ke rumah dan kantor. Mereka menarik kabel, menyambungnya dengan alat khusus, dan menguji kualitas sinyal.', 'Seiring perluasan internet fiber di Indonesia, kebutuhan teknisi ini terus naik. Pekerjaannya banyak di lapangan. Cocok buat kamu yang teliti, cekatan, dan suka teknologi jaringan. Bisa dimulai dari lulusan SMK TKJ atau elektro.'),
  ('Legal Officer', 'Legal officer menangani urusan hukum di dalam perusahaan, seperti menyusun dan memeriksa kontrak, mengurus perizinan, dan memastikan perusahaan tidak melanggar aturan.', 'Mereka juga menjadi penghubung dengan pengacara luar saat ada sengketa. Cocok buat kamu yang teliti, suka membaca dokumen, dan paham hukum bisnis. Biasanya lulusan S1 hukum.'),
  ('Panitera Pengadilan', 'Panitera pengadilan mencatat jalannya sidang dan mengelola berkas perkara di pengadilan. Mereka membuat berita acara sidang, mengurus dokumen putusan, dan membantu hakim dalam administrasi perkara.', 'Catatan mereka menjadi dokumen resmi yang sangat penting dalam proses hukum. Cocok buat kamu yang teliti, rapi, dan tertarik pada dunia peradilan. Biasanya lulusan S1 hukum melalui seleksi CPNS Mahkamah Agung.'),
  ('Notaris', 'Notaris membuat akta autentik, yaitu dokumen resmi yang punya kekuatan hukum kuat, seperti akta pendirian perusahaan, akta jual beli tanah, atau surat wasiat. Mereka memastikan perjanjian dibuat sesuai hukum.', 'Notaris membuka kantor sendiri setelah diangkat oleh Kementerian Hukum. Cocok buat kamu yang teliti, berintegritas, dan suka bidang hukum. Jalurnya S1 hukum, lalu S2 Magister Kenotariatan dan magang di kantor notaris.')
) as v(nama, p1, p2)
where c.career_name = v.nama
  and c.is_active;

do $$
declare n int;
begin
  select count(*) into n from public.careers
  where is_active and coalesce(description_source, '') <> 'kurasi';
  if n > 0 then
    raise notice '0050: % profesi aktif masih memakai deskripsi lama', n;
  end if;
end $$;

commit;
